contracts/AMMPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155Receiver.sol";
import "./CarbonCreditToken.sol";
import "./KYCRegistry.sol";
import "./Treasury.sol";

/**
 * @title AMMPool
 * @author EtherTrack
 * @notice x*y=k AMM for carbon credit swaps.
 *         Retail orders (< threshold) route here.
 *         Large orders use Marketplace order book.
 *
 * POOLS:
 *   Each pool is a (tokenId, ETH) pair.
 *   LP deposits carbon credits + ETH.
 *   Swappers get instant price via constant product formula.
 *   LP earns 0.3% swap fee.
 *
 * FORMULA:
 *   x = credit reserves
 *   y = ETH reserves
 *   k = x * y (constant)
 *   price = y / x
 *
 * FEES:
 *   0.3% LP fee (stays in pool, accrues to LPs)
 *   0.2% platform fee → Treasury
 *   Total: 0.5% per swap
 */
contract AMMPool is Ownable, ReentrancyGuard, IERC1155Receiver {

    CarbonCreditToken public creditToken;
    KYCRegistry       public kycRegistry;
    Treasury          public treasury;

    // ── Pool state ────────────────────────────────────────
    struct Pool {
        uint256 tokenId;
        uint256 creditReserve;  // x
        uint256 ethReserve;     // y
        uint256 totalShares;    // LP shares outstanding
        bool    active;
        string  name;
    }

    struct LPPosition {
        uint256 shares;
        uint256 creditDeposited;
        uint256 ethDeposited;
        uint256 depositedAt;
    }

    // poolId → Pool
    mapping(uint256 => Pool) public pools;
    // poolId → LP address → position
    mapping(uint256 => mapping(address => LPPosition)) public lpPositions;
    // tokenId → poolId (one pool per token type)
    mapping(uint256 => uint256) public tokenPool;

    uint256 private _nextPoolId;

    uint256 public constant LP_FEE_BPS       = 30;  // 0.3%
    uint256 public constant PLATFORM_FEE_BPS = 20;  // 0.2%
    uint256 public constant BPS_DENOMINATOR  = 10000;
    uint256 public constant MINIMUM_LIQUIDITY = 1000; // prevent dust attacks

    // ── Events ────────────────────────────────────────────
    event PoolCreated(uint256 indexed poolId, uint256 indexed tokenId, string name);
    event LiquidityAdded(uint256 indexed poolId, address indexed lp, uint256 credits, uint256 eth, uint256 shares);
    event LiquidityRemoved(uint256 indexed poolId, address indexed lp, uint256 credits, uint256 eth, uint256 shares);
    event KYCRegistryUpdated(address indexed oldRegistry, address indexed newRegistry);
    event Swapped(
        uint256 indexed poolId,
        address indexed trader,
        bool    creditIn,    // true = sold credits for ETH, false = bought credits with ETH
        uint256 amountIn,
        uint256 amountOut,
        uint256 fee
    );

    // ── Modifiers ─────────────────────────────────────────
    modifier onlyKYCVerified() {
        require(kycRegistry.isKYCVerified(msg.sender), "Not KYC verified");
        _;
    }

    modifier poolActive(uint256 poolId) {
        require(pools[poolId].active, "Pool not active");
        _;
    }

    // ── Constructor ───────────────────────────────────────
    constructor(
        address initialOwner,
        address creditTokenAddress,
        address kycRegistryAddress,
        address treasuryAddress
    ) Ownable(initialOwner) {
        creditToken = CarbonCreditToken(creditTokenAddress);
        kycRegistry = KYCRegistry(kycRegistryAddress);
        treasury    = Treasury(payable(treasuryAddress));
    }

    // ═══════════════════════════════════════════════════════
    // POOL MANAGEMENT
    // ═══════════════════════════════════════════════════════

    /**
     * @notice Create a new liquidity pool for a carbon credit token
     * @param tokenId  ERC-1155 token ID
     * @param name     Pool name (e.g. "India Renewable Pool")
     */
    function createPool(
        uint256 tokenId,
        string calldata name
    ) external onlyOwner returns (uint256 poolId) {
        require(tokenPool[tokenId] == 0, "Pool exists for this token");

        poolId = ++_nextPoolId;

        pools[poolId] = Pool({
            tokenId:       tokenId,
            creditReserve: 0,
            ethReserve:    0,
            totalShares:   0,
            active:        true,
            name:          name
        });

        tokenPool[tokenId] = poolId;
        emit PoolCreated(poolId, tokenId, name);
    }

    // ═══════════════════════════════════════════════════════
    // LIQUIDITY PROVISION
    // ═══════════════════════════════════════════════════════

    /**
     * @notice Add liquidity to a pool
     * @dev    LP deposits credits + ETH proportionally.
     *         First LP sets the initial price ratio.
     *         Subsequent LPs must match current ratio.
     *
     * @param poolId        Pool to add liquidity to
     * @param creditAmount  Credits to deposit
     */
    function addLiquidity(
        uint256 poolId,
        uint256 creditAmount
    ) external payable onlyKYCVerified poolActive(poolId) nonReentrant returns (uint256 shares) {
        Pool storage pool = pools[poolId];
        require(creditAmount > 0, "Credit amount must be > 0");
        require(msg.value > 0,    "ETH amount must be > 0");
        require(
            creditToken.balanceOf(msg.sender, pool.tokenId) >= creditAmount,
            "Insufficient credits"
        );

        if (pool.totalShares == 0) {
            // First LP — sets initial price
            shares = _sqrt(creditAmount * msg.value) - MINIMUM_LIQUIDITY;
            pool.totalShares = MINIMUM_LIQUIDITY; // lock minimum liquidity forever
        } else {
            // Subsequent LPs — must match ratio
            uint256 sharesByCredit = (creditAmount * pool.totalShares) / pool.creditReserve;
            uint256 sharesByEth    = (msg.value    * pool.totalShares) / pool.ethReserve;
            shares = _min(sharesByCredit, sharesByEth);
        }

        require(shares > 0, "Insufficient liquidity minted");

        pool.creditReserve += creditAmount;
        pool.ethReserve    += msg.value;
        pool.totalShares   += shares;

        lpPositions[poolId][msg.sender].shares           += shares;
        lpPositions[poolId][msg.sender].creditDeposited  += creditAmount;
        lpPositions[poolId][msg.sender].ethDeposited     += msg.value;
        lpPositions[poolId][msg.sender].depositedAt       = block.timestamp;

        // Transfer credits from LP to pool
        creditToken.safeTransferFrom(msg.sender, address(this), pool.tokenId, creditAmount, "");

        emit LiquidityAdded(poolId, msg.sender, creditAmount, msg.value, shares);
    }

    /**
     * @notice Remove liquidity from a pool
     * @param poolId Pool to remove from
     * @param shares LP shares to burn
     */
    function removeLiquidity(
        uint256 poolId,
        uint256 shares
    ) external poolActive(poolId) nonReentrant returns (uint256 creditAmount, uint256 ethAmount) {
        Pool storage pool = pools[poolId];
        LPPosition storage pos = lpPositions[poolId][msg.sender];

        require(pos.shares >= shares, "Insufficient shares");
        require(pool.totalShares > 0, "No liquidity");

        // Proportional share of reserves
        creditAmount = (shares * pool.creditReserve) / pool.totalShares;
        ethAmount    = (shares * pool.ethReserve)    / pool.totalShares;

        require(creditAmount > 0 && ethAmount > 0, "Insufficient liquidity burned");

        pos.shares           -= shares;
        pool.creditReserve   -= creditAmount;
        pool.ethReserve      -= ethAmount;
        pool.totalShares     -= shares;

        // Return credits to LP
        creditToken.safeTransferFrom(address(this), msg.sender, pool.tokenId, creditAmount, "");

        // Return ETH to LP
        (bool paid,) = msg.sender.call{value: ethAmount}("");
        require(paid, "ETH transfer failed");

        emit LiquidityRemoved(poolId, msg.sender, creditAmount, ethAmount, shares);
    }

    // ═══════════════════════════════════════════════════════
    // SWAP — x*y=k constant product
    // ═══════════════════════════════════════════════════════

    /**
     * @notice Buy credits with ETH via AMM
     * @dev    ETH in → credits out using x*y=k
     *         Best for small retail orders
     *
     * @param poolId      Pool to swap in
     * @param minCredits  Minimum credits to receive (slippage protection)
     */
    function swapETHForCredits(
        uint256 poolId,
        uint256 minCredits
    ) external payable onlyKYCVerified poolActive(poolId) nonReentrant returns (uint256 creditOut) {
        Pool storage pool = pools[poolId];
        require(msg.value > 0, "ETH amount must be > 0");
        require(pool.creditReserve > 0 && pool.ethReserve > 0, "Pool empty");

        // Deduct fees from input
        uint256 totalFee     = (msg.value * (LP_FEE_BPS + PLATFORM_FEE_BPS)) / BPS_DENOMINATOR;
        uint256 platformFee  = (msg.value * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        uint256 ethInAfterFee = msg.value - totalFee;

        // x*y=k: creditOut = (creditReserve * ethIn) / (ethReserve + ethIn)
        creditOut = (pool.creditReserve * ethInAfterFee) / (pool.ethReserve + ethInAfterFee);

        require(creditOut >= minCredits,        "Slippage exceeded");
        require(creditOut < pool.creditReserve, "Insufficient pool liquidity");

        // Update reserves
        pool.ethReserve    += ethInAfterFee;
        pool.creditReserve -= creditOut;

        // Transfer credits to buyer
        creditToken.safeTransferFrom(address(this), msg.sender, pool.tokenId, creditOut, "");

        // Platform fee to Treasury
        treasury.depositFee{value: platformFee}();

        emit Swapped(poolId, msg.sender, false, msg.value, creditOut, totalFee);
    }

    /**
     * @notice Sell credits for ETH via AMM
     * @dev    Credits in → ETH out using x*y=k
     *
     * @param poolId    Pool to swap in
     * @param credits   Credits to sell
     * @param minEth    Minimum ETH to receive (slippage protection)
     */
    function swapCreditsForETH(
        uint256 poolId,
        uint256 credits,
        uint256 minEth
    ) external onlyKYCVerified poolActive(poolId) nonReentrant returns (uint256 ethOut) {
        Pool storage pool = pools[poolId];
        require(credits > 0, "Credit amount must be > 0");
        require(pool.creditReserve > 0 && pool.ethReserve > 0, "Pool empty");
        require(
            creditToken.balanceOf(msg.sender, pool.tokenId) >= credits,
            "Insufficient credits"
        );

        // x*y=k: ethOut = (ethReserve * credits) / (creditReserve + credits)
        uint256 ethOutGross = (pool.ethReserve * credits) / (pool.creditReserve + credits);

        // Deduct fees from output
        uint256 totalFee    = (ethOutGross * (LP_FEE_BPS + PLATFORM_FEE_BPS)) / BPS_DENOMINATOR;
        uint256 platformFee = (ethOutGross * PLATFORM_FEE_BPS) / BPS_DENOMINATOR;
        ethOut = ethOutGross - totalFee;

        require(ethOut >= minEth,         "Slippage exceeded");
        require(ethOut < pool.ethReserve, "Insufficient pool liquidity");

        // Update reserves
        pool.creditReserve += credits;
        pool.ethReserve    -= ethOut;

        // Transfer credits from seller to pool
        creditToken.safeTransferFrom(msg.sender, address(this), pool.tokenId, credits, "");

        // Send ETH to seller
        (bool paid,) = msg.sender.call{value: ethOut}("");
        require(paid, "ETH transfer failed");

        // Platform fee to Treasury
        treasury.depositFee{value: platformFee}();

        emit Swapped(poolId, msg.sender, true, credits, ethOut, totalFee);
    }

    // ═══════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════

    /**
     * @notice Get current AMM price for a pool (ETH per credit)
     */
    function getPrice(uint256 poolId) external view returns (uint256) {
        Pool storage pool = pools[poolId];
        if (pool.creditReserve == 0) return 0;
        return (pool.ethReserve * 1e18) / pool.creditReserve;
    }

    /**
     * @notice Estimate credits out for ETH in
     */
    function quoteETHForCredits(uint256 poolId, uint256 ethIn) external view returns (uint256 creditOut, uint256 fee) {
        Pool storage pool = pools[poolId];
        if (pool.creditReserve == 0 || pool.ethReserve == 0) return (0, 0);
        fee      = (ethIn * (LP_FEE_BPS + PLATFORM_FEE_BPS)) / BPS_DENOMINATOR;
        uint256 ethInAfterFee = ethIn - fee;
        creditOut = (pool.creditReserve * ethInAfterFee) / (pool.ethReserve + ethInAfterFee);
    }

    /**
     * @notice Estimate ETH out for credits in
     */
    function quoteCreditsForETH(uint256 poolId, uint256 credits) external view returns (uint256 ethOut, uint256 fee) {
        Pool storage pool = pools[poolId];
        if (pool.creditReserve == 0 || pool.ethReserve == 0) return (0, 0);
        uint256 ethOutGross = (pool.ethReserve * credits) / (pool.creditReserve + credits);
        fee    = (ethOutGross * (LP_FEE_BPS + PLATFORM_FEE_BPS)) / BPS_DENOMINATOR;
        ethOut = ethOutGross - fee;
    }

    function getPool(uint256 poolId) external view returns (Pool memory) {
        return pools[poolId];
    }

    function getLPPosition(uint256 poolId, address lp) external view returns (LPPosition memory) {
        return lpPositions[poolId][lp];
    }

    function totalPools() external view returns (uint256) { return _nextPoolId; }

    // ── Internal math ─────────────────────────────────────
    function _sqrt(uint256 x) internal pure returns (uint256 y) {
        if (x == 0) return 0;
        uint256 z = (x + 1) / 2;
        y = x;
        while (z < y) { y = z; z = (x / z + z) / 2; }
    }

    function _min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }

    // ── ERC1155 Receiver ──────────────────────────────────
    function onERC1155Received(
        address, address, uint256, uint256, bytes calldata
    ) external pure override returns (bytes4) {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(
        address, address, uint256[] calldata, uint256[] calldata, bytes calldata
    ) external pure override returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == type(IERC1155Receiver).interfaceId;
    }

    /// @notice Repoint this contract at a different KYCRegistry deployment
    ///         without redeploying AMMPool. Existing pools, liquidity, and
    ///         balances are untouched.
    function setKYCRegistry(address newRegistry) external onlyOwner {
        require(newRegistry != address(0), "Invalid registry address");
        emit KYCRegistryUpdated(address(kycRegistry), newRegistry);
        kycRegistry = KYCRegistry(newRegistry);
    }

    receive() external payable {}
}

contracts/AuditTrail.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

// ─────────────────────────────────────────────────────────────────────────────
// EtherTrack — GHG Audit Trail Contract v2
// Network:  Ethereum Sepolia Testnet (chainId 11155111)
//           → Production: Polygon Mainnet (chainId 137)
//             Just redeploy — no contract changes needed.
//
// Production fixes v2:
//   [FIX-ORG-SCOPE]   companyId can now be org_id OR user_id (both UUIDs as
//                     strings) — matches routes/audit.js resolveScope()
//   [FIX-EVENT-FAIL]  ChainVerifyFailed event added for monitoring
//   [FIX-META-BYTES]  metaJson length checked in bytes (UTF-8 safe)
//   [FIX-AMENDMENT]   addAmendment() added — locked inventory can have
//                     verifier-approved amendments logged
//   [FIX-VERIFIER]    approvedVerifier mapping — only approved verifiers
//                     can call addAmendment()
//   [FIX-BATCH]       batchLogEntries() added — reduces gas for bulk imports
//
// Architecture:
//   • Every audit action is written on-chain as an AuditEntry.
//   • Entries are hash-chained: each entry stores prev entry's hash.
//     Tampering breaks the chain — verifiable by anyone via verifyChain().
//   • Server-side relayer wallet (owner) submits txs — users never need gas.
//   • Entries grouped by (companyId, year) — each has its own sub-chain.
//   • Read functions are public — no auth needed to verify.
//
// Deployment:
//   npx hardhat run scripts/deploy.js --network sepolia
//   npx hardhat run scripts/deploy.js --network polygon  (production)
// ─────────────────────────────────────────────────────────────────────────────

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract AuditTrail is Ownable, Pausable, ReentrancyGuard {

    // ── Action types ─────────────────────────────────────────────────────────
    uint8 public constant ACTION_CREATE    = 1;
    uint8 public constant ACTION_UPDATE    = 2;
    uint8 public constant ACTION_DELETE    = 3;
    uint8 public constant ACTION_VERIFY    = 4;
    uint8 public constant ACTION_SIGN      = 5;
    uint8 public constant ACTION_LOCK      = 6;
    uint8 public constant ACTION_IMPORT    = 7;
    uint8 public constant ACTION_COMMENT   = 8;
    uint8 public constant ACTION_AMENDMENT = 9; // [FIX-AMENDMENT]

    // ── Structs ───────────────────────────────────────────────────────────────
    struct AuditEntry {
        uint256 id;
        string  companyId;   // org_id or user_id (UUID string)
        uint16  year;
        uint8   action;
        string  message;
        string  metaJson;
        bytes32 entryHash;   // SHA-256 computed server-side
        bytes32 prevHash;
        uint256 timestamp;
        address relayer;
    }

    // ── Storage ───────────────────────────────────────────────────────────────
    // companyId => year => AuditEntry[]
    mapping(string => mapping(uint16 => AuditEntry[])) private _entries;

    // companyId => year => last entry hash
    mapping(string => mapping(uint16 => bytes32)) private _lastHash;

    // companyId => year => locked
    mapping(string => mapping(uint16 => bool)) private _locked;

    // companyId => year => entry count
    mapping(string => mapping(uint16 => uint256)) public entryCounts;

    // [FIX-VERIFIER] companyId => year => verifier address => approved
    mapping(string => mapping(uint16 => mapping(address => bool))) public approvedVerifiers;

    // Global stats
    uint256 public totalEntries;
    uint256 public totalCompanies;

    // ── Events ────────────────────────────────────────────────────────────────
    event EntryLogged(
        string  indexed companyId,
        uint16  indexed year,
        uint256         entryId,
        uint8           action,
        bytes32         entryHash,
        bytes32         prevHash,
        uint256         timestamp
    );

    event InventoryLocked(
        string  indexed companyId,
        uint16  indexed year,
        address         lockedBy,
        uint256         timestamp
    );

    // [FIX-AMENDMENT] Amendment logged on locked inventory
    event AmendmentLogged(
        string  indexed companyId,
        uint16  indexed year,
        uint256         entryId,
        address         verifier,
        uint256         timestamp
    );

    // [FIX-EVENT-FAIL] Chain verification failure event for monitoring
    event ChainVerifyFailed(
        string  indexed companyId,
        uint16  indexed year,
        uint256         brokenAt,
        uint256         timestamp
    );

    // [FIX-VERIFIER] Verifier approved/revoked
    event VerifierApproved(string indexed companyId, uint16 indexed year, address verifier);
    event VerifierRevoked(string indexed companyId, uint16 indexed year, address verifier);

    // ── Modifiers ─────────────────────────────────────────────────────────────
    modifier notLocked(string calldata companyId, uint16 year) {
        require(!_locked[companyId][year], "Inventory locked for this year");
        _;
    }

    modifier onlyLocked(string calldata companyId, uint16 year) {
        require(_locked[companyId][year], "Inventory not locked");
        _;
    }

    modifier validYear(uint16 year) {
        require(year >= 2000 && year <= 2100, "Invalid year");
        _;
    }

    modifier nonEmptyString(string calldata s) {
        require(bytes(s).length > 0, "String cannot be empty");
        _;
    }

    // [FIX-VERIFIER] Only approved verifier can amend locked inventory
    modifier onlyApprovedVerifier(string calldata companyId, uint16 year) {
        require(
            approvedVerifiers[companyId][year][msg.sender] || msg.sender == owner(),
            "Not an approved verifier for this company/year"
        );
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────
    constructor(address initialOwner) Ownable(initialOwner) {}

    // ── Core write — only relayer (owner) can call ────────────────────────────
    /**
     * @notice Log an audit entry on-chain.
     * @param companyId  EtherTrack org_id or user_id (UUID string)
     * @param year       Reporting year
     * @param action     ACTION_* constant
     * @param message    Human-readable message (max 2000 bytes)
     * @param metaJson   JSON metadata string (max 2000 bytes)
     * @param entryHash  SHA-256 hash computed server-side
     *
     * NOTE: entryHash is pre-computed server-side and passed in.
     *       This keeps the hash algorithm consistent with the backend.
     *       Verifiers recompute off-chain and compare — no trust needed.
     */
    function logEntry(
        string  calldata companyId,
        uint16           year,
        uint8            action,
        string  calldata message,
        string  calldata metaJson,
        bytes32          entryHash
    )
        external
        onlyOwner
        whenNotPaused
        nonReentrant
        notLocked(companyId, year)
        validYear(year)
        nonEmptyString(companyId)
        nonEmptyString(message)
        returns (uint256 entryId)
    {
        require(action >= 1 && action <= 8, "Invalid action type");
        // [FIX-META-BYTES] Check bytes length not char length
        require(bytes(message).length  <= 2000, "Message too long");
        require(bytes(metaJson).length <= 2000, "Meta too long");

        bytes32 prevHash = _lastHash[companyId][year];
        entryId          = entryCounts[companyId][year];

        AuditEntry memory entry = AuditEntry({
            id:        entryId,
            companyId: companyId,
            year:      year,
            action:    action,
            message:   message,
            metaJson:  metaJson,
            entryHash: entryHash,
            prevHash:  prevHash,
            timestamp: block.timestamp,
            relayer:   msg.sender
        });

        _entries[companyId][year].push(entry);
        _lastHash[companyId][year]    = entryHash;
        entryCounts[companyId][year] += 1;
        totalEntries                 += 1;

        emit EntryLogged(
            companyId, year, entryId,
            action, entryHash, prevHash,
            block.timestamp
        );

        return entryId;
    }

    // ── [FIX-BATCH] Batch log — reduces gas for bulk imports ─────────────────
    /**
     * @notice Log multiple entries in a single transaction.
     *         Entries must be for the same companyId and year.
     *         Max 50 entries per batch.
     */
    function batchLogEntries(
        string   calldata companyId,
        uint16            year,
        uint8[]  calldata actions,
        string[] calldata messages,
        string[] calldata metaJsons,
        bytes32[] calldata entryHashes
    )
        external
        onlyOwner
        whenNotPaused
        nonReentrant
        notLocked(companyId, year)
        validYear(year)
        nonEmptyString(companyId)
    {
        uint256 count = actions.length;
        require(count > 0,   "Empty batch");
        require(count <= 50, "Batch too large - max 50");
        require(
            count == messages.length &&
            count == metaJsons.length &&
            count == entryHashes.length,
            "Array length mismatch"
        );

        for (uint256 i = 0; i < count; i++) {
            require(actions[i] >= 1 && actions[i] <= 8, "Invalid action type");
            require(bytes(messages[i]).length  <= 2000, "Message too long");
            require(bytes(metaJsons[i]).length <= 2000, "Meta too long");

            bytes32 prevHash = _lastHash[companyId][year];
            uint256 entryId  = entryCounts[companyId][year];

            _entries[companyId][year].push(AuditEntry({
                id:        entryId,
                companyId: companyId,
                year:      year,
                action:    actions[i],
                message:   messages[i],
                metaJson:  metaJsons[i],
                entryHash: entryHashes[i],
                prevHash:  prevHash,
                timestamp: block.timestamp,
                relayer:   msg.sender
            }));

            _lastHash[companyId][year]    = entryHashes[i];
            entryCounts[companyId][year] += 1;
            totalEntries                 += 1;

            emit EntryLogged(
                companyId, year, entryId,
                actions[i], entryHashes[i], prevHash,
                block.timestamp
            );
        }
    }

    // ── Lock inventory ────────────────────────────────────────────────────────
    /**
     * @notice Lock an inventory year — no more logEntry() calls allowed.
     *         Amendments still possible via addAmendment() with verifier approval.
     */
    function lockInventory(
        string calldata companyId,
        uint16          year
    )
        external
        onlyOwner
        whenNotPaused
        validYear(year)
        nonEmptyString(companyId)
    {
        require(!_locked[companyId][year], "Already locked");
        _locked[companyId][year] = true;
        emit InventoryLocked(companyId, year, msg.sender, block.timestamp);
    }

    // ── [FIX-AMENDMENT] Add amendment to locked inventory ────────────────────
    /**
     * @notice Log an amendment to a locked inventory.
     *         Only callable by approved verifiers or the owner.
     *         Used for ISO 14064-3 corrective actions after data freeze.
     */
    function addAmendment(
        string  calldata companyId,
        uint16           year,
        string  calldata message,
        string  calldata metaJson,
        bytes32          entryHash
    )
        external
        whenNotPaused
        nonReentrant
        onlyLocked(companyId, year)
        validYear(year)
        nonEmptyString(companyId)
        nonEmptyString(message)
        onlyApprovedVerifier(companyId, year)
    {
        require(bytes(message).length  <= 2000, "Message too long");
        require(bytes(metaJson).length <= 2000, "Meta too long");

        bytes32 prevHash = _lastHash[companyId][year];
        uint256 entryId  = entryCounts[companyId][year];

        _entries[companyId][year].push(AuditEntry({
            id:        entryId,
            companyId: companyId,
            year:      year,
            action:    ACTION_AMENDMENT,
            message:   message,
            metaJson:  metaJson,
            entryHash: entryHash,
            prevHash:  prevHash,
            timestamp: block.timestamp,
            relayer:   msg.sender
        }));

        _lastHash[companyId][year]    = entryHash;
        entryCounts[companyId][year] += 1;
        totalEntries                 += 1;

        emit AmendmentLogged(companyId, year, entryId, msg.sender, block.timestamp);
    }

    // ── [FIX-VERIFIER] Verifier management ───────────────────────────────────
    /**
     * @notice Approve a verifier address to submit amendments for a company/year.
     *         Called by the relayer after verifier is confirmed in the backend.
     */
    function approveVerifier(
        string  calldata companyId,
        uint16           year,
        address          verifier
    )
        external
        onlyOwner
        validYear(year)
        nonEmptyString(companyId)
    {
        require(verifier != address(0), "Invalid verifier address");
        approvedVerifiers[companyId][year][verifier] = true;
        emit VerifierApproved(companyId, year, verifier);
    }

    function revokeVerifier(
        string  calldata companyId,
        uint16           year,
        address          verifier
    )
        external
        onlyOwner
        validYear(year)
        nonEmptyString(companyId)
    {
        approvedVerifiers[companyId][year][verifier] = false;
        emit VerifierRevoked(companyId, year, verifier);
    }

    // ── Read functions — public ───────────────────────────────────────────────
    function getEntry(
        string calldata companyId,
        uint16          year,
        uint256         entryId
    ) external view returns (AuditEntry memory) {
        require(entryId < entryCounts[companyId][year], "Entry not found");
        return _entries[companyId][year][entryId];
    }

    function getAllEntries(
        string calldata companyId,
        uint16          year
    ) external view returns (AuditEntry[] memory) {
        return _entries[companyId][year];
    }

    // Get a page of entries — prevents gas limit issues on large chains
    function getEntriesPaged(
        string calldata companyId,
        uint16          year,
        uint256         offset,
        uint256         limit
    ) external view returns (AuditEntry[] memory page) {
        AuditEntry[] storage all = _entries[companyId][year];
        uint256 total = all.length;
        if (offset >= total) return new AuditEntry[](0);
        uint256 end  = offset + limit;
        if (end > total) end = total;
        uint256 size = end - offset;
        page = new AuditEntry[](size);
        for (uint256 i = 0; i < size; i++) {
            page[i] = all[offset + i];
        }
        return page;
    }

    function getLastHash(
        string calldata companyId,
        uint16          year
    ) external view returns (bytes32) {
        return _lastHash[companyId][year];
    }

    function isLocked(
        string calldata companyId,
        uint16          year
    ) external view returns (bool) {
        return _locked[companyId][year];
    }

    function getEntryCount(
        string calldata companyId,
        uint16          year
    ) external view returns (uint256) {
        return entryCounts[companyId][year];
    }

    /**
     * @notice Verify the hash chain integrity for a (companyId, year).
     *         Returns (intact, brokenAt).
     *         brokenAt = type(uint256).max if chain is intact.
     *         Anyone can call this — no trust required.
     *
     * [FIX-EVENT-FAIL] Emits ChainVerifyFailed if broken (view functions
     * cannot emit events, so monitoring should call this off-chain and
     * check the return value).
     */
    function verifyChain(
        string calldata companyId,
        uint16          year
    ) external view returns (bool intact, uint256 brokenAt) {
        AuditEntry[] storage chain = _entries[companyId][year];
        uint256 len = chain.length;

        if (len == 0) return (true, type(uint256).max);

        for (uint256 i = 1; i < len; i++) {
            if (chain[i].prevHash != chain[i - 1].entryHash) {
                return (false, i);
            }
        }
        return (true, type(uint256).max);
    }

    // ── Admin ─────────────────────────────────────────────────────────────────
    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

contracts/CarbonCreditToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/token/ERC1155/extensions/ERC1155Supply.sol";
import "@openzeppelin/contracts/token/ERC1155/extensions/ERC1155Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./KYCRegistry.sol";

/**
 * @title CarbonCreditToken
 * @author EtherTrack
 * @notice ERC-1155 token where each tokenId = one carbon credit project.
 *         Each unit of a tokenId = 1 tonne CO2 equivalent.
 *         ANY KYC-verified wallet can mint, list, and trade credits.
 */
contract CarbonCreditToken is ERC1155, ERC1155Supply, ERC1155Burnable, Ownable, Pausable, ReentrancyGuard {

    KYCRegistry public kycRegistry;

    // ── [NEW] Operator role — a backend-controlled wallet (or the Marketplace
    // contract itself) authorized to execute actions on behalf of users who
    // pay via INR/Razorpay, so those users never need to sign a MetaMask
    // transaction for routine listing/buying/retiring. The operator can only
    // ever move tokens that a wallet ALREADY legitimately holds/escrowed —
    // it cannot mint into existence or bypass KYC checks. ──────────────────
    address public operator;

    event OperatorUpdated(address indexed oldOperator, address indexed newOperator);
    event KYCRegistryUpdated(address indexed oldRegistry, address indexed newRegistry);

    modifier onlyOperator() {
        require(
            msg.sender == operator || msg.sender == owner(),
            "CarbonCreditToken: not operator"
        );
        _;
    }

    // ── Credit Standards ──────────────────────────────────
    enum Standard { VCS, GS, CDM, ACR }

    // ── MintParams Struct (fixes stack too deep) ──────────
    struct MintParams {
        address  to;
        uint256  amount;
        string   projectName;
        string   location;
        Standard standard;
        string   projectType;
        string   developer;
        uint256  vintageYear;
        uint256  expiryDate;
        string   serialNumber;
        string   metadataURI;
    }

    // ── Credit Metadata ───────────────────────────────────
    struct CreditMetadata {
        string   projectName;
        string   location;
        Standard standard;
        string   projectType;
        string   developer;
        uint256  vintageYear;
        uint256  expiryDate;
        string   serialNumber;
        string   metadataURI;
        bool     active;
        address  registeredBy;
        uint256  registeredAt;
    }

    // ── State ─────────────────────────────────────────────
    uint256 private _nextTokenId;

    mapping(uint256 => CreditMetadata)              public creditMetadata;
    mapping(uint256 => uint256)                     public totalRetired;
    mapping(address => mapping(uint256 => uint256)) public retiredBy;
    mapping(string  => uint256)                     public serialToTokenId;
    mapping(string  => bool)                        public serialRegistered;

    // ── Events ────────────────────────────────────────────
    event CreditMinted(
        uint256 indexed tokenId,
        address indexed to,
        uint256 amount,
        string  projectName,
        Standard standard,
        string  serialNumber
    );
    event CreditRetired(
        uint256 indexed tokenId,
        address indexed retiredBy,
        uint256 amount,
        string  projectName
    );

    // ── Modifiers ─────────────────────────────────────────
    modifier onlyKYCVerified(address wallet) {
        require(kycRegistry.isKYCVerified(wallet), "Wallet not KYC verified");
        _;
    }

    // ANY KYC verified wallet can mint — no whitelist needed
    modifier onlyAuthorizedMinter() {
        require(
            kycRegistry.isKYCVerified(msg.sender) || msg.sender == owner(),
            "Must be KYC verified to mint"
        );
        _;
    }

    // ── Constructor ───────────────────────────────────────
    constructor(
        address initialOwner,
        address kycRegistryAddress
    ) ERC1155("") Ownable(initialOwner) {
        kycRegistry = KYCRegistry(kycRegistryAddress);
    }

    // ── Mint ──────────────────────────────────────────────

    /**
     * @notice Register a new carbon credit project and mint tokens.
     *         ANY KYC verified wallet can call this.
     *
     * BLOCKCHAIN MIGRATION: Replaces handleRegister() in Portfolio.js
     */
    function mintCredit(MintParams calldata p)
        external
        onlyAuthorizedMinter
        whenNotPaused
        onlyKYCVerified(p.to)
        returns (uint256)
    {
        require(p.amount > 0,                      "Amount must be > 0");
        require(bytes(p.serialNumber).length > 0,  "Serial number required");
        require(!serialRegistered[p.serialNumber], "Serial already registered");
        require(p.expiryDate > block.timestamp,    "Expiry must be in future");

        uint256 tokenId = _nextTokenId++;

        creditMetadata[tokenId] = CreditMetadata({
            projectName:  p.projectName,
            location:     p.location,
            standard:     p.standard,
            projectType:  p.projectType,
            developer:    p.developer,
            vintageYear:  p.vintageYear,
            expiryDate:   p.expiryDate,
            serialNumber: p.serialNumber,
            metadataURI:  p.metadataURI,
            active:       true,
            registeredBy: msg.sender,
            registeredAt: block.timestamp
        });

        serialToTokenId[p.serialNumber]  = tokenId;
        serialRegistered[p.serialNumber] = true;

        _mint(p.to, tokenId, p.amount, "");

        emit CreditMinted(tokenId, p.to, p.amount, p.projectName, p.standard, p.serialNumber);
        return tokenId;
    }

    /**
     * @notice Mint additional credits for an existing tokenId
     */
    function mintAdditional(
        address to,
        uint256 tokenId,
        uint256 amount
    ) external onlyAuthorizedMinter whenNotPaused onlyKYCVerified(to) {
        require(creditMetadata[tokenId].active, "Credit project not active");
        _mint(to, tokenId, amount, "");
    }

    // ── Retire ────────────────────────────────────────────

    /**
     * @notice Permanently retire credits — burns tokens, offsets carbon.
     */
    function retireCredit(
        uint256 tokenId,
        uint256 amount
    ) external whenNotPaused nonReentrant onlyKYCVerified(msg.sender) {
        require(amount > 0,                               "Amount must be > 0");
        require(balanceOf(msg.sender, tokenId) >= amount, "Insufficient credits");

        totalRetired[tokenId]          += amount;
        retiredBy[msg.sender][tokenId] += amount;

        if (totalSupply(tokenId) - amount == 0) {
            creditMetadata[tokenId].active = false;
        }

        _burn(msg.sender, tokenId, amount);

        emit CreditRetired(tokenId, msg.sender, amount, creditMetadata[tokenId].projectName);
    }

    /**
     * @notice [NEW] Operator-executed retirement — lets the backend retire
     *         credits on a user's behalf (e.g. a user who paid via INR/UPI
     *         and never personally holds a MetaMask session open) WITHOUT
     *         requiring their signature. This does NOT let the operator
     *         retire credits arbitrarily — `beneficiary` must already
     *         genuinely hold `amount` of `tokenId` on-chain (checked below,
     *         same as the self-service retireCredit above), and the burn is
     *         attributed to `beneficiary`, not the operator, so GHG
     *         Protocol / BRSR retirement records remain correctly credited
     *         to whoever actually retired the credit.
     */
    function retireCreditFor(
        address beneficiary,
        uint256 tokenId,
        uint256 amount
    ) external onlyOperator whenNotPaused nonReentrant onlyKYCVerified(beneficiary) {
        require(amount > 0,                                  "Amount must be > 0");
        require(balanceOf(beneficiary, tokenId) >= amount,   "Insufficient credits");

        totalRetired[tokenId]              += amount;
        retiredBy[beneficiary][tokenId]    += amount;

        if (totalSupply(tokenId) - amount == 0) {
            creditMetadata[tokenId].active = false;
        }

        _burn(beneficiary, tokenId, amount);

        emit CreditRetired(tokenId, beneficiary, amount, creditMetadata[tokenId].projectName);
    }

    // ── Transfer Override (KYC check) ─────────────────────
    function safeTransferFrom(
        address from,
        address to,
        uint256 id,
        uint256 amount,
        bytes memory data
    ) public override whenNotPaused {
        // Allow marketplace contract transfers without KYC check
        // (marketplace is already KYC-gated at entry)
        if (from != address(0) && !kycRegistry.isKYCVerified(from)) {
            // Allow if it's a contract (marketplace escrow transfers)
            uint256 size;
            assembly { size := extcodesize(from) }
            if (size == 0) revert("Sender not KYC verified");
        }
        if (to != address(0) && !kycRegistry.isKYCVerified(to)) {
            uint256 size;
            assembly { size := extcodesize(to) }
            if (size == 0) revert("Receiver not KYC verified");
        }
        super.safeTransferFrom(from, to, id, amount, data);
    }

    // ── View Functions ────────────────────────────────────
    function uri(uint256 tokenId) public view override returns (string memory) {
        return creditMetadata[tokenId].metadataURI;
    }

    function getCreditMetadata(uint256 tokenId) external view returns (CreditMetadata memory) {
        return creditMetadata[tokenId];
    }

    function getTotalRetired(uint256 tokenId) external view returns (uint256) {
        return totalRetired[tokenId];
    }

    function getRetiredBy(address wallet, uint256 tokenId) external view returns (uint256) {
        return retiredBy[wallet][tokenId];
    }

    function isExpired(uint256 tokenId) public view returns (bool) {
        return block.timestamp > creditMetadata[tokenId].expiryDate;
    }

    function getNextTokenId() external view returns (uint256) {
        return _nextTokenId;
    }

    // ── Admin ─────────────────────────────────────────────
    function pause()   external onlyOwner { _pause();   }
    function unpause() external onlyOwner { _unpause(); }

    /// @notice Repoint this contract at a different KYCRegistry deployment
    ///         without redeploying CarbonCreditToken. Existing balances,
    ///         mints, and burns are untouched.
    function setKYCRegistry(address newRegistry) external onlyOwner {
        require(newRegistry != address(0), "Invalid registry address");
        emit KYCRegistryUpdated(address(kycRegistry), newRegistry);
        kycRegistry = KYCRegistry(newRegistry);
    }

    // [NEW] Set the backend operator wallet authorized to call
    // retireCreditFor() on behalf of beneficiaries.
    function setOperator(address _operator) external onlyOwner {
        require(_operator != address(0), "Zero address");
        emit OperatorUpdated(operator, _operator);
        operator = _operator;
    }

    // ── Required overrides ────────────────────────────────
    function _update(
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory values
    ) internal override(ERC1155, ERC1155Supply) {
        super._update(from, to, ids, values);
    }
}

contracts/CreditLedger.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title CreditLedger
 * @author EtherTrack
 * @notice Records carbon credit ownership changes (mint, list, delist, buy,
 *         sell, retire) as an immutable, tamper-evident on-chain audit trail
 *         — WITHOUT requiring each individual user to hold a personal
 *         Ethereum wallet.
 *
 *         All actual CarbonCreditToken (ERC-1155) balances are held in ONE
 *         pooled custody address (the platform Treasury / Marketplace
 *         escrow) — never distributed to individual user addresses. Real
 *         ownership — who owns how many credits of what — lives in
 *         EtherTrack's database, exactly as before. What THIS contract adds
 *         is a permanent, independently-verifiable, hashed record of every
 *         change to that ownership, so the database's claims can never be
 *         silently altered after the fact without it being detectable by
 *         anyone, using nothing but a block explorer.
 *
 *         This mirrors EmissionRegistry.sol's existing pattern exactly:
 *         logEmission()/recordOffset() don't move any tokens either — they
 *         just write structured, timestamped, hashed records. CreditLedger
 *         applies that same proven pattern to credit ownership instead of
 *         emissions data.
 *
 *         A user is identified here by `userId` — keccak256 of their
 *         internal platform user UUID, NOT a wallet address they need to
 *         generate, fund, or hold private keys for. This removes MetaMask/
 *         wallet-extension friction entirely for users who only ever trade
 *         via INR — while keeping every single action fully on-chain,
 *         timestamped, and tamper-evident.
 *
 *         Users who DO want true self-custody remain free to withdraw their
 *         credits to a real wallet of their own at any time (a genuine
 *         on-chain CarbonCreditToken transfer out of the pool to their
 *         address) — at which point they become a normal self-custody
 *         holder, verifiable the traditional way (their own balanceOf()).
 */
contract CreditLedger is Ownable, Pausable {

    // ── Action Types ───────────────────────────────────────
    enum ActionType { MINT, LIST, DELIST, BUY, SELL, RETIRE, WITHDRAW_TO_WALLET }

    // ── Structs ───────────────────────────────────────────
    struct OwnershipLog {
        bytes32     userId;       // keccak256(platform user UUID) — not a wallet
        uint256     tokenId;      // CarbonCreditToken tokenId
        int256      amountDelta;  // positive = credited, negative = debited
        ActionType  actionType;
        uint256     loggedAt;     // Unix timestamp
        bytes32     refHash;      // keccak256 of the canonical DB record —
                                  // lets anyone verify the DB row this log
                                  // corresponds to hasn't been altered since
        string      note;         // optional context (project name, trade id, etc.)
    }

    // ── State ─────────────────────────────────────────────
    OwnershipLog[] private _logs;

    // userId => log IDs
    mapping(bytes32 => uint256[]) public userLogs;
    // userId => tokenId => running balance (credits currently held)
    mapping(bytes32 => mapping(uint256 => uint256)) public userTokenBalance;
    // userId => tokenId => total ever retired
    mapping(bytes32 => mapping(uint256 => uint256)) public userTokenRetired;
    // tokenId => total held across all ledger users (should reconcile with
    // the pooled custody wallet's real on-chain CarbonCreditToken balance —
    // see reconciliation note at bottom of file)
    mapping(uint256 => uint256) public totalLedgerBalance;

    // ── [NEW] Operator role — same pattern as CarbonCreditToken.sol.
    // A backend-controlled wallet authorized to write ledger entries. Only
    // ever writes what the platform's own settlement logic determines
    // happened — this contract has no independent way to verify DB claims,
    // it only guarantees that whatever WAS logged cannot be altered
    // afterward. The trust boundary is "did the operator log honestly",
    // not "can the log be tampered with after the fact" (it cannot).
    address public operator;

    event OperatorUpdated(address indexed oldOperator, address indexed newOperator);

    modifier onlyOperator() {
        require(msg.sender == operator || msg.sender == owner(), "CreditLedger: not operator");
        _;
    }

    // ── Events ────────────────────────────────────────────
    event OwnershipLogged(
        uint256 indexed logId,
        bytes32 indexed userId,
        uint256 indexed tokenId,
        int256  amountDelta,
        ActionType actionType,
        bytes32 refHash
    );

    event CreditRetiredLogged(
        uint256 indexed logId,
        bytes32 indexed userId,
        uint256 tokenId,
        uint256 amount,
        bytes32 refHash
    );

    // ── Constructor ───────────────────────────────────────
    constructor(address initialOwner) Ownable(initialOwner) {}

    /// @notice Owner-only. Sets the backend wallet allowed to write ledger entries.
    function setOperator(address _operator) external onlyOwner {
        require(_operator != address(0), "CreditLedger: zero address");
        emit OperatorUpdated(operator, _operator);
        operator = _operator;
    }

    // ── Core Functions ────────────────────────────────────

    /**
     * @notice Log a change in a user's credit ownership — mint, list,
     *         delist, buy, or sell. Does NOT move any real tokens; the
     *         actual CarbonCreditToken balance stays in pooled custody
     *         throughout. This is purely the tamper-evident record of what
     *         the platform's database claims happened.
     * @param userId       keccak256 of the platform user's internal UUID
     * @param tokenId      CarbonCreditToken tokenId this log concerns
     * @param amountDelta  positive = user gained credits, negative = user
     *                     gave up credits (list/sell) — reverts if a
     *                     negative delta would take the user's running
     *                     balance below zero, preventing an inconsistent
     *                     ledger from ever being written
     * @param actionType   MINT / LIST / DELIST / BUY / SELL / WITHDRAW_TO_WALLET
     *                     (use logRetirement() below for RETIRE, which has
     *                     its own dedicated event + running totals for
     *                     GHG Protocol / BRSR certificate purposes)
     * @param refHash      keccak256 of the canonical DB record fields for
     *                     this change (mirrors Marketplace.sol's
     *                     inrTradeHashes pattern) — lets anyone independently
     *                     verify the DB row hasn't been altered since
     * @param note         optional human-readable context
     */
    function logOwnershipChange(
        bytes32    userId,
        uint256    tokenId,
        int256     amountDelta,
        ActionType actionType,
        bytes32    refHash,
        string calldata note
    ) external onlyOperator whenNotPaused returns (uint256 logId) {
        require(userId != bytes32(0), "CreditLedger: zero userId");
        require(amountDelta != 0,      "CreditLedger: zero delta");
        require(actionType != ActionType.RETIRE, "CreditLedger: use logRetirement() for retirement");

        uint256 currentBalance = userTokenBalance[userId][tokenId];

        if (amountDelta < 0) {
            uint256 debit = uint256(-amountDelta);
            require(currentBalance >= debit, "CreditLedger: insufficient ledger balance");
            userTokenBalance[userId][tokenId] = currentBalance - debit;
            totalLedgerBalance[tokenId]       -= debit;
        } else {
            uint256 credit = uint256(amountDelta);
            userTokenBalance[userId][tokenId] = currentBalance + credit;
            totalLedgerBalance[tokenId]       += credit;
        }

        logId = _logs.length;
        _logs.push(OwnershipLog({
            userId:      userId,
            tokenId:     tokenId,
            amountDelta: amountDelta,
            actionType:  actionType,
            loggedAt:    block.timestamp,
            refHash:     refHash,
            note:        note
        }));

        userLogs[userId].push(logId);

        emit OwnershipLogged(logId, userId, tokenId, amountDelta, actionType, refHash);
    }

    /**
     * @notice Log a retirement — permanently reduces the user's ledger
     *         balance and records it via a dedicated event + running
     *         retired-total, separate from logOwnershipChange() above,
     *         because retirement certificates (GHG Protocol / BRSR) need
     *         a clean, unambiguous, independently-queryable trail distinct
     *         from ordinary buy/sell activity.
     */
    function logRetirement(
        bytes32 userId,
        uint256 tokenId,
        uint256 amount,
        bytes32 refHash
    ) external onlyOperator whenNotPaused returns (uint256 logId) {
        require(userId != bytes32(0), "CreditLedger: zero userId");
        require(amount > 0,           "CreditLedger: zero amount");

        uint256 currentBalance = userTokenBalance[userId][tokenId];
        require(currentBalance >= amount, "CreditLedger: insufficient ledger balance");

        userTokenBalance[userId][tokenId] = currentBalance - amount;
        totalLedgerBalance[tokenId]       -= amount;
        userTokenRetired[userId][tokenId] += amount;

        logId = _logs.length;
        _logs.push(OwnershipLog({
            userId:      userId,
            tokenId:     tokenId,
            amountDelta: -int256(amount),
            actionType:  ActionType.RETIRE,
            loggedAt:    block.timestamp,
            refHash:     refHash,
            note:        ""
        }));

        userLogs[userId].push(logId);

        emit CreditRetiredLogged(logId, userId, tokenId, amount, refHash);
    }

    // ── View Functions ────────────────────────────────────

    function getLog(uint256 logId) external view returns (OwnershipLog memory) {
        return _logs[logId];
    }

    function getUserLogs(bytes32 userId) external view returns (uint256[] memory) {
        return userLogs[userId];
    }

    function getUserBalance(bytes32 userId, uint256 tokenId) external view returns (uint256) {
        return userTokenBalance[userId][tokenId];
    }

    function getUserRetired(bytes32 userId, uint256 tokenId) external view returns (uint256) {
        return userTokenRetired[userId][tokenId];
    }

    function totalLogs() external view returns (uint256) {
        return _logs.length;
    }

    /// @notice Helper so the backend and any outside auditor compute the
    ///         same userId hash the same way, every time.
    function computeUserId(string calldata userUuid) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(userUuid));
    }

    // ── Admin ─────────────────────────────────────────────
    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

// ─────────────────────────────────────────────────────────────────────────────
// RECONCILIATION NOTE (not enforced on-chain — an operational discipline,
// same as any custodial ledger):
//
// totalLedgerBalance[tokenId] tracked by this contract should, at any point
// in time, equal the pooled custody wallet's actual
// CarbonCreditToken.balanceOf(poolAddress, tokenId) on-chain. If they ever
// diverge, that's an immediate, checkable signal something is wrong — worth
// building a scheduled job that compares these two numbers and alerts if
// they don't match, the same way a bank reconciles its ledger against its
// actual vault holdings.
// ─────────────────────────────────────────────────────────────────────────────

contracts/EmissionRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./KYCRegistry.sol";

/**
 * @title EmissionRegistry
 * @author EtherTrack
 * @notice Records company/user emission data on-chain.
 *         Immutable audit trail for carbon accounting.
 *
 * BLOCKCHAIN MIGRATION: Replaces EmissionTracking.js local state
 */
contract EmissionRegistry is Ownable, Pausable {

    KYCRegistry public kycRegistry;

    // ── Emission Categories ───────────────────────────────
    enum Scope { SCOPE_1, SCOPE_2, SCOPE_3 } // GHG Protocol scopes

    // ── Structs ───────────────────────────────────────────
    struct EmissionLog {
        address  wallet;
        uint256  loggedAt;       // Unix timestamp
        uint256  period;         // Unix timestamp of emission period (month/year)
        uint256  energyKWh;      // Monthly energy consumption (kWh)
        uint256  transportKm;    // Monthly transport (km)
        uint256  wasteKg;        // Monthly waste (kg)
        uint256  totalCO2e;      // Total CO2 equivalent (in kg, multiply by 1e3 for precision)
        uint256  creditsNeeded;  // Tonnes CO2 to offset
        Scope    scope;
        string   notes;          // Optional additional info
    }

    struct OffsetRecord {
        address  wallet;
        uint256  tokenId;        // CarbonCreditToken tokenId used for offset
        uint256  amount;         // Credits used
        uint256  co2Offset;      // kg CO2 offset
        uint256  offsetAt;
        uint256  emissionLogId;  // Reference to the emission log
    }

    // ── State ─────────────────────────────────────────────
    EmissionLog[]  private _emissionLogs;
    OffsetRecord[] private _offsetRecords;

    // wallet => emission log IDs
    mapping(address => uint256[]) public userEmissionLogs;
    // wallet => total CO2e emitted (kg)
    mapping(address => uint256)   public totalEmitted;
    // wallet => total CO2 offset (kg)
    mapping(address => uint256)   public totalOffset;

    // Emission factors (India, multiplied by 1e6 for precision)
    // Source: CEA 2023, MoRTH, CPCB
    uint256 public constant ENERGY_FACTOR    = 820000; // 0.82 kg CO2/kWh × 1e6
    uint256 public constant TRANSPORT_FACTOR = 210000; // 0.21 kg CO2/km  × 1e6
    uint256 public constant WASTE_FACTOR     = 50000;  // 0.05 kg CO2/kg  × 1e6
    uint256 public constant PRECISION        = 1e6;

    // ── Events ────────────────────────────────────────────
    event EmissionLogged(
        uint256 indexed logId,
        address indexed wallet,
        uint256 totalCO2e,
        uint256 creditsNeeded,
        uint256 period
    );
    event EmissionOffset(
        uint256 indexed logId,
        address indexed wallet,
        uint256 tokenId,
        uint256 amount,
        uint256 co2Offset
    );
    event KYCRegistryUpdated(address indexed oldRegistry, address indexed newRegistry);

    // ── Modifiers ─────────────────────────────────────────
    modifier onlyKYCVerified() {
        require(kycRegistry.isKYCVerified(msg.sender), "Wallet not KYC verified");
        _;
    }

    // ── Constructor ───────────────────────────────────────
    constructor(address initialOwner, address kycRegistryAddress) Ownable(initialOwner) {
        kycRegistry = KYCRegistry(kycRegistryAddress);
    }

    // ── Core Functions ────────────────────────────────────

    /**
     * @notice Log monthly emission data on-chain
     * @param period      Unix timestamp of the emission month
     * @param energyKWh   Energy consumption in kWh
     * @param transportKm Transport distance in km
     * @param wasteKg     Waste generated in kg
     * @param scope       GHG Protocol scope
     * @param notes       Optional notes
     *
     * BLOCKCHAIN MIGRATION: Replaces EmissionTracking.js calcEmissions()
     */
    function logEmission(
        uint256 period,
        uint256 energyKWh,
        uint256 transportKm,
        uint256 wasteKg,
        Scope   scope,
        string  calldata notes
    ) external onlyKYCVerified whenNotPaused returns (uint256 logId) {
        require(period <= block.timestamp, "Period cannot be in future");

        // Calculate total CO2e (in kg, using precision factor)
        uint256 energyCO2   = (energyKWh   * ENERGY_FACTOR)    / PRECISION;
        uint256 transportCO2= (transportKm * TRANSPORT_FACTOR)  / PRECISION;
        uint256 wasteCO2    = (wasteKg     * WASTE_FACTOR)      / PRECISION;
        uint256 totalCO2e   = energyCO2 + transportCO2 + wasteCO2;

        // Credits needed = ceil(totalCO2e / 1000) — 1 credit = 1 tonne = 1000 kg
        uint256 creditsNeeded = (totalCO2e + 999) / 1000;

        logId = _emissionLogs.length;

        _emissionLogs.push(EmissionLog({
            wallet:       msg.sender,
            loggedAt:     block.timestamp,
            period:       period,
            energyKWh:    energyKWh,
            transportKm:  transportKm,
            wasteKg:      wasteKg,
            totalCO2e:    totalCO2e,
            creditsNeeded:creditsNeeded,
            scope:        scope,
            notes:        notes
        }));

        userEmissionLogs[msg.sender].push(logId);
        totalEmitted[msg.sender] += totalCO2e;

        emit EmissionLogged(logId, msg.sender, totalCO2e, creditsNeeded, period);
        return logId;
    }

    /**
     * @notice Record that a user offset their emissions using credits
     *         Called by Marketplace after retire transaction
     */
    function recordOffset(
        address wallet,
        uint256 tokenId,
        uint256 amount,
        uint256 co2Offset,
        uint256 emissionLogId
    ) external whenNotPaused {
        // Only callable by authorized contracts (Marketplace) or owner
        require(msg.sender == owner(), "Not authorized");

        uint256 recordId = _offsetRecords.length;

        _offsetRecords.push(OffsetRecord({
            wallet:        wallet,
            tokenId:       tokenId,
            amount:        amount,
            co2Offset:     co2Offset,
            offsetAt:      block.timestamp,
            emissionLogId: emissionLogId
        }));

        totalOffset[wallet] += co2Offset;

        emit EmissionOffset(recordId, wallet, tokenId, amount, co2Offset);
    }

    // ── View Functions ────────────────────────────────────

    function getEmissionLog(uint256 logId) external view returns (EmissionLog memory) {
        return _emissionLogs[logId];
    }

    function getUserEmissionLogs(address wallet) external view returns (uint256[] memory) {
        return userEmissionLogs[wallet];
    }

    function getTotalEmitted(address wallet) external view returns (uint256) {
        return totalEmitted[wallet];
    }

    function getNetEmissions(address wallet) external view returns (int256) {
        return int256(totalEmitted[wallet]) - int256(totalOffset[wallet]);
    }

    function calculateEmissions(
        uint256 energyKWh,
        uint256 transportKm,
        uint256 wasteKg
    ) external pure returns (uint256 totalCO2e, uint256 creditsNeeded) {
        uint256 energyCO2    = (energyKWh   * ENERGY_FACTOR)   / PRECISION;
        uint256 transportCO2 = (transportKm * TRANSPORT_FACTOR) / PRECISION;
        uint256 wasteCO2     = (wasteKg     * WASTE_FACTOR)     / PRECISION;
        totalCO2e     = energyCO2 + transportCO2 + wasteCO2;
        creditsNeeded = (totalCO2e + 999) / 1000;
    }

    function totalEmissionLogs() external view returns (uint256) {
        return _emissionLogs.length;
    }

    // ── Admin ─────────────────────────────────────────────
    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /// @notice Repoint this contract at a different KYCRegistry deployment
    ///         without redeploying EmissionRegistry. Existing emission
    ///         logs and offset records are untouched.
    function setKYCRegistry(address newRegistry) external onlyOwner {
        require(newRegistry != address(0), "Invalid registry address");
        emit KYCRegistryUpdated(address(kycRegistry), newRegistry);
        kycRegistry = KYCRegistry(newRegistry);
    }
}

contracts/KYCRegistry.sol.content:
// SPDX-License-Identifier: MIT


pragma solidity ^0.8.26;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title KYCRegistry
 * @author EtherTrack
 * @notice Stores KYC verification status keyed by a server-issued identity
 *         hash — NOT by wallet address. Only a personal data hash is
 *         stored on-chain (not raw PII). Actual KYC documents stay
 *         off-chain (IPFS/Backend).
 *
 * IDENTITY HASH CONVENTION (must match CreditLedger.sol/backend exactly):
 *   userIdHash = keccak256(abi.encodePacked(userUuid))
 *   In Solidity that's the same as JS `ethers.keccak256(ethers.toUtf8Bytes(userUuid))`
 *   — no prefix, no salt. This is the SAME derivation CreditLedger.sol's
 *   computeUserId() and services/creditLedger.js's computeUserIdHash()
 *   already use, and the same `users.user_id_hash` column already cached
 *   for that purpose is reused here — one identity hash, shared across
 *   every wallet-free on-chain contract on the platform.
 *
 * WHY IDENTITY-KEYED, NOT WALLET-KEYED:
 *   EtherTrack supports INR-only trading (wallet + Razorpay), so a user
 *   can be a fully verified, compliant trader without ever owning or
 *   connecting a crypto wallet. Keying KYC records by wallet address would
 *   mean KYC literally could not exist on-chain until a user connected
 *   MetaMask — an artificial dependency with no compliance basis. Keying
 *   by a stable server-issued identity hash means:
 *     - KYC is written on-chain the moment an operator approves it,
 *       regardless of whether the user has (or ever gets) a wallet.
 *     - If/when a wallet is later bound, it's linked via linkWallet() and
 *       isKYCVerified(wallet) keeps working exactly as before, so
 *       EmissionRegistry / Marketplace / CarbonCreditToken / AMMPool — all
 *       of which check kycRegistry.isKYCVerified(msg.sender) — require
 *       ZERO changes.
 *
 * COMPLIANCE NOTE (FIU-IND / PMLA):
 *   Self-verification is not possible. Under PMLA 2002 and FIU-IND
 *   guidelines, the Reporting Entity (not the user) is responsible for
 *   identity verification. All KYC approvals must flow through an
 *   authorised KYC Operator via verifyKYC(). This requirement concerns WHO
 *   authorises the write (only the backend operator, exactly as before) —
 *   it does not require the on-chain key to be a wallet address. Flow:
 *
 *     User submits docs → Backend/AdminDashboard reviews → Operator calls
 *     verifyKYC(userIdHash, dataHash) → identity verified on-chain
 *     → (optionally, whenever it happens) operator calls linkWallet()
 *       to associate a wallet once the user connects one.
 *
 * BLOCKCHAIN MIGRATION: Replaces AuthContext kycCompleted flag
 */
contract KYCRegistry is Ownable, Pausable {

    // ── Structs ───────────────────────────────────────────
    struct KYCRecord {
        bool      verified;
        uint256   verifiedAt;    // timestamp
        uint256   expiresAt;     // KYC validity (2 years)
        bytes32   kycDataHash;   // keccak256 of off-chain KYC data
        address   verifiedBy;    // authorised operator only
    }

    // ── State ─────────────────────────────────────────────
    // userIdHash = keccak256(userUuid) — see convention note above
    mapping(bytes32 => KYCRecord) private _kycRecords;

    // wallet => userIdHash, populated only once a user binds a wallet
    mapping(address => bytes32) public walletToUser;
    // userIdHash => wallet, reverse lookup (address(0) if none bound yet)
    mapping(bytes32 => address) public userToWallet;

    // Authorized KYC operators (backend verifiers)
    mapping(address => bool) public kycOperators;

    uint256 public constant KYC_VALIDITY = 2 * 365 days;

    // ── Events ────────────────────────────────────────────
    event KYCVerified(bytes32 indexed userIdHash, address indexed operator, uint256 expiresAt);
    event KYCRevoked(bytes32 indexed userIdHash, address indexed operator, string reason);
    event WalletLinked(bytes32 indexed userIdHash, address indexed wallet, address indexed operator);
    event WalletUnlinked(bytes32 indexed userIdHash, address indexed wallet, address indexed operator);
    event KYCOperatorAdded(address indexed operator);
    event KYCOperatorRemoved(address indexed operator);

    // ── Modifiers ─────────────────────────────────────────
    modifier onlyKYCOperator() {
        require(kycOperators[msg.sender] || msg.sender == owner(), "Not a KYC operator");
        _;
    }

    // ── Constructor ───────────────────────────────────────
    constructor(address initialOwner) Ownable(initialOwner) {
        kycOperators[initialOwner] = true;
    }

    // ── KYC Operator Management ───────────────────────────
    function addKYCOperator(address operator) external onlyOwner {
        require(operator != address(0), "Invalid operator address");
        kycOperators[operator] = true;
        emit KYCOperatorAdded(operator);
    }

    function removeKYCOperator(address operator) external onlyOwner {
        kycOperators[operator] = false;
        emit KYCOperatorRemoved(operator);
    }

    // ── Core KYC Functions ────────────────────────────────

    /**
     * @notice Verify a user's KYC — must be called by an authorised
     *         KYC Operator (backend/admin) after off-chain review.
     *         Requires NO wallet — identity is keyed by userIdHash alone,
     *         so this can (and should) fire the instant KYC is approved,
     *         whether or not the user has ever touched MetaMask.
     *
     * @param userIdHash   keccak256(userUuid) — see convention note above
     * @param kycDataHash  keccak256(idType:idNumber:phone:fullName) or business-KYC equivalent.
     *                     Computed off-chain; raw PII never touches chain.
     */
    function verifyKYC(
        bytes32 userIdHash,
        bytes32 kycDataHash
    ) external onlyKYCOperator whenNotPaused {
        require(userIdHash != bytes32(0), "Invalid userIdHash");
        _writeKYCRecord(userIdHash, kycDataHash, msg.sender);
    }

    /**
     * @notice Link a wallet to an already-verified identity. Optional —
     *         only relevant for users who choose to trade on-chain (ETH
     *         path). INR-only traders never need this called at all.
     *         Overwrites any previous link for this userIdHash.
     */
    function linkWallet(bytes32 userIdHash, address wallet) external onlyKYCOperator whenNotPaused {
        require(wallet != address(0), "Invalid wallet address");
        require(_kycRecords[userIdHash].verified, "Identity not KYC verified");

        // Clear a stale reverse-link if this wallet was previously linked elsewhere
        bytes32 prevUser = walletToUser[wallet];
        if (prevUser != bytes32(0) && prevUser != userIdHash) {
            userToWallet[prevUser] = address(0);
        }
        // Clear this identity's previous wallet link, if any
        address prevWallet = userToWallet[userIdHash];
        if (prevWallet != address(0)) {
            walletToUser[prevWallet] = bytes32(0);
        }

        walletToUser[wallet] = userIdHash;
        userToWallet[userIdHash] = wallet;
        emit WalletLinked(userIdHash, wallet, msg.sender);
    }

    /**
     * @notice Remove a wallet link — fraud/compliance action, or user
     *         requested a wallet change.
     */
    function unlinkWallet(address wallet) external onlyKYCOperator {
        bytes32 userIdHash = walletToUser[wallet];
        require(userIdHash != bytes32(0), "Wallet not linked");
        walletToUser[wallet] = bytes32(0);
        userToWallet[userIdHash] = address(0);
        emit WalletUnlinked(userIdHash, wallet, msg.sender);
    }

    /**
     * @notice Revoke KYC — fraud/compliance action.
     */
    function revokeKYC(
        bytes32 userIdHash,
        string calldata reason
    ) external onlyKYCOperator {
        require(_kycRecords[userIdHash].verified, "KYC not verified");
        _kycRecords[userIdHash].verified = false;
        emit KYCRevoked(userIdHash, msg.sender, reason);
    }

    // ── Internal ──────────────────────────────────────────
    function _writeKYCRecord(
        bytes32 userIdHash,
        bytes32 kycDataHash,
        address verifier
    ) internal {
        uint256 expiresAt = block.timestamp + KYC_VALIDITY;
        _kycRecords[userIdHash] = KYCRecord({
            verified:    true,
            verifiedAt:  block.timestamp,
            expiresAt:   expiresAt,
            kycDataHash: kycDataHash,
            verifiedBy:  verifier
        });
        emit KYCVerified(userIdHash, verifier, expiresAt);
    }

    // ── View Functions ────────────────────────────────────

    /**
     * @notice Backward-compatible wallet-keyed check. Used by
     *         EmissionRegistry / Marketplace / CarbonCreditToken / AMMPool
     *         via msg.sender — unchanged signature so those contracts need
     *         NO modification. Resolves wallet -> userIdHash -> record.
     */
    function isKYCVerified(address wallet) public view returns (bool) {
        bytes32 userIdHash = walletToUser[wallet];
        if (userIdHash == bytes32(0)) return false;
        return isKYCVerifiedById(userIdHash);
    }

    /**
     * @notice Identity-keyed check — for backend/off-chain use, works for
     *         users who have no wallet at all (INR-only traders).
     */
    function isKYCVerifiedById(bytes32 userIdHash) public view returns (bool) {
        KYCRecord memory record = _kycRecords[userIdHash];
        return record.verified && block.timestamp < record.expiresAt;
    }

    function getKYCRecord(bytes32 userIdHash) external view returns (KYCRecord memory) {
        return _kycRecords[userIdHash];
    }

    function getKYCRecordByWallet(address wallet) external view returns (KYCRecord memory) {
        return _kycRecords[walletToUser[wallet]];
    }

    function getKYCExpiry(bytes32 userIdHash) external view returns (uint256) {
        return _kycRecords[userIdHash].expiresAt;
    }

    /// @notice Helper so backend/auditors compute the identical hash every
    ///         time — mirrors CreditLedger.sol's computeUserId() exactly.
    function computeUserId(string calldata userUuid) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(userUuid));
    }

    // ── Admin ─────────────────────────────────────────────
    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

contracts/Marketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC1155/IERC1155Receiver.sol";
import "@openzeppelin/contracts/governance/TimelockController.sol";
import "./CarbonCreditToken.sol";
import "./KYCRegistry.sol";
import "./Treasury.sol";

/**
 * Minimal TimelockController interface for external reference
 */
interface ITimelockController {
    function PROPOSER_ROLE() external view returns (bytes32);
    function EXECUTOR_ROLE() external view returns (bytes32);
    function ADMIN_ROLE() external view returns (bytes32);
    function minDelay() external view returns (uint256);
    function getBlockNumber() external view returns (uint256);
    function getMinDelay() external view returns (uint256);
    function isOperation(bytes32 id) external view returns (bool);
    function isOperationPending(bytes32 id) external view returns (bool);
    function isOperationReady(bytes32 id) external view returns (bool);
    function isOperationDone(bytes32 id) external view returns (bool);
    function schedule(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) external returns (bytes32);
    function execute(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt
    ) external payable returns (bytes32);
}

/**
 * EtherTrack Marketplace v2
 * ─────────────────────────────────────────────────────────────────────────────
 * CHANGES vs v1:
 *
 * [NEW] logINRTrade()       — logs INR wallet trades on-chain after DB settlement
 * [NEW] logRazorpayTrade()  — logs direct Razorpay checkout trades on-chain
 * [NEW] batchLogINRTrades() — batch version (gas efficient, up to 20 trades/tx)
 * [NEW] verifyTrade()       — public verification for any trade (all modes)
 * [NEW] INRTradeLogged event — emitted for every off-chain settled trade
 * [NEW] signerWallet        — backend hot wallet authorized to call log functions
 * [NEW] inrTradeHashes      — mapping to prevent duplicate logs
 * [NEW] setKYCRegistry()    — repoint at a new KYCRegistry deployment without
 *                             redeploying Marketplace itself (existing
 *                             listings/trades untouched)
 *
 * WHAT DIDN'T CHANGE:
 *   All ETH trade logic (buyCredit, placeBuyOrder, cancelBuyOrder, matching)
 *   Fee structure (BUYER_FEE_BPS=50, SELLER_FEE_BPS=50 → 1% total to Treasury)
 *   All view functions, structs, events
 *   Treasury, CarbonCreditToken integrations
 *
 * HOW IT WORKS:
 *   ETH trades  → buyCredit() fires CreditTraded event (already on-chain)
 *   INR trades  → backend calls logINRTrade() after DB atomic settlement
 *   Razorpay    → backend calls logRazorpayTrade() after Razorpay verify
 *   All 3 modes → verifyTrade() lets anyone confirm a trade happened
 *
 * [FIX-NATSPEC v2.1] Fixed a NatSpec doc-comment bug in verifyTrade() below:
 *   its doc comment had a return-value tag written as "payMode" but the
 *   function's actual 4th return value is named `loggedPayMode`. Solidity's
 *   compiler enforces that documented return names match real return
 *   parameter names exactly, and Hardhat failed the entire build over this
 *   mismatch (HH600). No behavior changed — only the doc comment text.
 * ─────────────────────────────────────────────────────────────────────────────
 */
contract Marketplace is Ownable, Pausable, ReentrancyGuard, IERC1155Receiver {

    CarbonCreditToken public creditToken;
    KYCRegistry       public kycRegistry;
    Treasury          public treasury;

    // ── NEW: Backend signer wallet ────────────────────────────────────────────
    address public signerWallet;

    // ── NEW: Timelock controller for admin operations ──────────────────────
    ITimelockController public timelockController;

    enum OrderSide   { BUY, SELL }
    enum OrderStatus { OPEN, FILLED, PARTIALLY_FILLED, CANCELLED, EXPIRED }

    // ── Payment mode (matches backend paymentMode column) ─────────────────────
    uint8 public constant MODE_INR_WALLET   = 0;
    uint8 public constant MODE_RAZORPAY     = 1;
    uint8 public constant MODE_ETH          = 2;

    struct Listing {
        uint256 listingId;
        address seller;
        uint256 tokenId;
        uint256 amount;
        uint256 amountRemaining;
        uint256 pricePerUnit;      // ETH wei per credit
        uint256 pricePerUnitINR;   // INR price (whole rupees, e.g. 1200 = ₹1200)
        uint256 listedAt;
        uint256 expiresAt;
        bool    active;
    }

    struct BuyOrder {
        uint256     orderId;
        address     buyer;
        uint256     tokenId;
        uint256     amount;
        uint256     amountFilled;
        uint256     limitPrice;
        uint256     ethEscrowed;
        OrderStatus status;
        uint256     createdAt;
        uint256     expiresAt;
    }

    struct Trade {
        uint256 tradeId;
        uint256 listingId;
        uint256 buyOrderId;
        address buyer;
        address seller;
        uint256 tokenId;
        uint256 amount;
        uint256 pricePerUnit;
        uint256 pricePerUnitINR;
        uint256 totalPrice;
        uint256 buyerFee;
        uint256 sellerFee;
        uint256 totalFee;
        uint256 tradedAt;
        bool    isAMM;
    }

    // ── NEW: INR/Razorpay trade log entry ─────────────────────────────────────
    struct INRTradeLog {
        bytes32 tradeId;      // keccak256 of DB UUID
        uint256 tokenId;
        uint256 quantity;
        uint256 priceINR;     // price per credit in paise (₹ × 100)
        uint8   payMode;      // MODE_INR_WALLET or MODE_RAZORPAY
        address buyer;        // may be zero if no wallet bound
        address seller;
        uint256 timestamp;
        bytes32 tradeHash;    // keccak256 of all fields — tamper-evident
        uint256 blockLogged;
    }

    uint256 private _nextListingId;
    uint256 private _nextOrderId;
    uint256 private _nextTradeId;

    mapping(uint256 => Listing)  public listings;
    mapping(uint256 => BuyOrder) public buyOrders;
    mapping(uint256 => Trade)    public trades;

    mapping(address => uint256[]) public sellerListings;
    mapping(address => uint256[]) public buyerOrders;
    mapping(address => uint256[]) public buyerTrades;
    mapping(address => uint256[]) public sellerTrades;
    mapping(uint256 => uint256[]) public tokenListings;
    mapping(uint256 => uint256[]) public tokenBuyOrders;

    // ── NEW: INR trade log storage ────────────────────────────────────────────
    // bytes32 tradeId (DB UUID as keccak256) → log entry
    mapping(bytes32 => INRTradeLog) public inrTradeLogs;
    // bytes32 tradeId → stored hash (for fast verification)
    mapping(bytes32 => bytes32)     public inrTradeHashes;

    address public ammPool;
    uint256 public ammThreshold = 100;

    uint256 public constant BUYER_FEE_BPS   = 50;    // 0.5%
    uint256 public constant SELLER_FEE_BPS  = 50;    // 0.5%
    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant MAX_DURATION     = 90 days;
    uint256 public constant DEFAULT_DURATION = 30 days;

    // ── Events ────────────────────────────────────────────────────────────────

    // Existing ETH trade event — unchanged
    event CreditListed(
        uint256 indexed listingId,
        address indexed seller,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 pricePerUnit,
        uint256 pricePerUnitINR
    );
    event ListingCancelled(uint256 indexed listingId, address indexed seller);
    event ListingUpdated(uint256 indexed listingId, uint256 newPrice, uint256 newPriceINR);
    event KYCRegistryUpdated(address indexed oldRegistry, address indexed newRegistry);

    event BuyOrderPlaced(
        uint256 indexed orderId,
        address indexed buyer,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 limitPrice,
        uint256 ethEscrowed
    );
    event BuyOrderCancelled(uint256 indexed orderId, address indexed buyer, uint256 ethRefunded);
    event BuyOrderFilled(uint256 indexed orderId, uint256 amountFilled, uint256 amountRemaining);

    event CreditTraded(
        uint256 indexed tradeId,
        uint256 indexed listingId,
        uint256 indexed buyOrderId,
        address buyer,
        address seller,
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerUnit,
        uint256 pricePerUnitINR,
        uint256 totalPrice,
        uint256 buyerFee,
        uint256 sellerFee,
        uint256 totalFee,
        bool    isAMM
    );

    // ── NEW EVENTS ────────────────────────────────────────────────────────────

    /**
     * @dev Emitted for every INR wallet or Razorpay trade logged on-chain.
     *      Indexed on tradeId and tokenId for fast off-chain querying.
     *      Anyone can verify by calling verifyTrade().
     */
    event INRTradeLogged(
        bytes32 indexed tradeId,    // keccak256 of DB UUID
        uint256 indexed tokenId,
        uint256         quantity,
        uint256         priceINR,   // paise (₹ × 100)
        uint8           payMode,    // 0=INR_WALLET, 1=RAZORPAY
        address indexed buyer,      // zero if no wallet bound
        address         seller,
        bytes32         tradeHash,  // tamper-evident proof
        uint256         timestamp
    );

    event SignerWalletUpdated(address indexed oldSigner, address indexed newSigner);

    event AMMPoolSet(address indexed ammPool);
    event AMMThresholdUpdated(uint256 newThreshold);
    event MatchExecuted(uint256 listingId, uint256 buyOrderId, uint256 amount, uint256 price);

    // ── Modifiers ─────────────────────────────────────────────────────────────

    modifier onlyKYCVerified() {
        require(
            kycRegistry.isKYCVerified(msg.sender),
            "Not authorized: wallet not KYC verified"
        );
        _;
    }

    modifier onlySigner() {
        require(msg.sender == signerWallet, "Marketplace: not signer wallet");
        _;
    }

    modifier listingExists(uint256 listingId) {
        require(listings[listingId].active, "Listing not active");
        require(block.timestamp < listings[listingId].expiresAt, "Listing expired");
        _;
    }

    modifier buyOrderExists(uint256 orderId) {
        require(
            buyOrders[orderId].status == OrderStatus.OPEN ||
            buyOrders[orderId].status == OrderStatus.PARTIALLY_FILLED,
            "Buy order not open"
        );
        require(block.timestamp < buyOrders[orderId].expiresAt, "Buy order expired");
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────

    constructor(
        address initialOwner,
        address creditTokenAddress,
        address kycRegistryAddress,
        address treasuryAddress,
        address _signerWallet          // NEW: backend hot wallet
    ) Ownable(initialOwner) {
        require(_signerWallet != address(0), "Marketplace: zero signer");
        creditToken  = CarbonCreditToken(creditTokenAddress);
        kycRegistry  = KYCRegistry(kycRegistryAddress);
        treasury     = Treasury(payable(treasuryAddress));
        signerWallet = _signerWallet;
    }

    // ═════════════════════════════════════════════════════════════════════════
    // NEW: INR / RAZORPAY ON-CHAIN LOGGING
    // Called by EtherTrack backend AFTER DB settlement confirms successfully.
    // Gas is paid by the platform (signer wallet has MATIC).
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * @notice Log a single INR wallet or Razorpay trade on-chain.
     *         Called by the backend signer wallet after atomic DB settlement.
     *
     * @param tradeId    keccak256(abi.encodePacked(dbTradeUUID)) — unique per trade
     * @param tokenId    carbon credit token ID
     * @param quantity   credits purchased
     * @param priceINR   price per credit in PAISE (₹1000 = 100000 paise)
     * @param payMode    0 = INR_WALLET, 1 = RAZORPAY
     * @param buyer      buyer's bound wallet (address(0) if none)
     * @param seller     seller's bound wallet
     * @param timestamp  unix timestamp of DB settlement
     */
    function logINRTrade(
        bytes32 tradeId,
        uint256 tokenId,
        uint256 quantity,
        uint256 priceINR,
        uint8   payMode,
        address buyer,
        address seller,
        uint256 timestamp
    ) external onlySigner whenNotPaused {
        require(
            payMode == MODE_INR_WALLET || payMode == MODE_RAZORPAY,
            "Marketplace: use buyCredit for ETH trades"
        );
        require(inrTradeHashes[tradeId] == bytes32(0), "Marketplace: trade already logged");
        require(quantity > 0,   "Marketplace: zero quantity");
        require(priceINR > 0,   "Marketplace: zero price");
        require(seller != address(0), "Marketplace: zero seller");

        bytes32 hash = keccak256(abi.encodePacked(
            tradeId, tokenId, quantity, priceINR,
            payMode, buyer, seller, timestamp
        ));

        inrTradeHashes[tradeId] = hash;
        inrTradeLogs[tradeId]   = INRTradeLog({
            tradeId:     tradeId,
            tokenId:     tokenId,
            quantity:    quantity,
            priceINR:    priceINR,
            payMode:     payMode,
            buyer:       buyer,
            seller:      seller,
            timestamp:   timestamp,
            tradeHash:   hash,
            blockLogged: block.number
        });

        emit INRTradeLogged(
            tradeId, tokenId, quantity, priceINR,
            payMode, buyer, seller, hash, timestamp
        );
    }

    /**
     * @notice Batch log up to 20 INR/Razorpay trades in one transaction.
     *         Used by the hourly cron for gas efficiency.
     *         Skips duplicates silently (idempotent).
     */
    function batchLogINRTrades(
        bytes32[] calldata tradeIds,
        uint256[] calldata tokenIds,
        uint256[] calldata quantities,
        uint256[] calldata pricesINR,
        uint8[]   calldata payModes,
        address[] calldata buyers,
        address[] calldata sellers,
        uint256[] calldata timestamps
    ) external onlySigner whenNotPaused {
        uint256 len = tradeIds.length;
        require(len <= 20,  "Marketplace: max 20 per batch");
        require(
            len == tokenIds.length &&
            len == quantities.length &&
            len == pricesINR.length &&
            len == payModes.length &&
            len == buyers.length &&
            len == sellers.length &&
            len == timestamps.length,
            "Marketplace: array length mismatch"
        );

        for (uint256 i = 0; i < len; i++) {
            // Skip duplicates — safe to retry
            if (inrTradeHashes[tradeIds[i]] != bytes32(0)) continue;
            // Skip invalid modes
            if (payModes[i] != MODE_INR_WALLET && payModes[i] != MODE_RAZORPAY) continue;

            bytes32 hash = keccak256(abi.encodePacked(
                tradeIds[i], tokenIds[i], quantities[i], pricesINR[i],
                payModes[i], buyers[i], sellers[i], timestamps[i]
            ));

            inrTradeHashes[tradeIds[i]] = hash;
            inrTradeLogs[tradeIds[i]] = INRTradeLog({
                tradeId:     tradeIds[i],
                tokenId:     tokenIds[i],
                quantity:    quantities[i],
                priceINR:    pricesINR[i],
                payMode:     payModes[i],
                buyer:       buyers[i],
                seller:      sellers[i],
                timestamp:   timestamps[i],
                tradeHash:   hash,
                blockLogged: block.number
            });

            emit INRTradeLogged(
                tradeIds[i], tokenIds[i], quantities[i], pricesINR[i],
                payModes[i], buyers[i], sellers[i], hash, timestamps[i]
            );
        }
    }

    /**
     * @notice [NEW] Actually SETTLES an INR/Razorpay purchase on-chain —
     *         transfers the escrowed credit tokens from this contract to
     *         the buyer's real wallet, records a Trade entry, and writes
     *         the same tamper-evident audit log as logINRTrade(), all in
     *         one transaction. This is the function that was MISSING
     *         previously: logINRTrade() alone only wrote an audit record
     *         and never moved any tokens, which is why buyers' on-chain
     *         balances stayed at zero despite the DB marking trades
     *         'completed'. Called by the backend signer wallet once a
     *         buyer's INR/Razorpay payment is confirmed. Requires zero
     *         signature from either buyer or seller — the tokens are
     *         already escrowed in this contract from listing time.
     *
     * @param listingId      the listing being sold from
     * @param buyer          buyer's wallet (must be KYC verified)
     * @param amount         quantity of credits to transfer
     * @param priceINR       price per credit in PAISE (₹1000 = 100000 paise)
     * @param tradeId        keccak256(abi.encodePacked(dbTradeUUID)) — unique per trade
     * @param payMode        MODE_INR_WALLET or MODE_RAZORPAY
     * @param timestamp      unix timestamp of DB settlement
     */
    function settleINRTrade(
        uint256 listingId,
        address buyer,
        uint256 amount,
        uint256 priceINR,
        bytes32 tradeId,
        uint8   payMode,
        uint256 timestamp
    ) external onlySigner whenNotPaused nonReentrant listingExists(listingId) returns (uint256 recordedTradeId) {
        require(
            payMode == MODE_INR_WALLET || payMode == MODE_RAZORPAY,
            "Marketplace: use buyCredit for ETH trades"
        );
        require(inrTradeHashes[tradeId] == bytes32(0), "Marketplace: trade already logged");
        require(kycRegistry.isKYCVerified(buyer),      "Buyer not KYC verified");
        require(amount > 0,                             "Amount must be > 0");
        require(priceINR > 0,                           "Marketplace: zero price");

        Listing storage listing = listings[listingId];
        require(listing.seller != buyer,               "Cannot buy own listing");
        require(amount <= listing.amountRemaining,      "Exceeds available amount");

        listing.amountRemaining -= amount;
        if (listing.amountRemaining == 0) listing.active = false;

        // Record the trade in the same `trades` mapping ETH trades use, so
        // getTrade()/getBuyerTrades()/getSellerTrades() work identically
        // regardless of payment mode.
        recordedTradeId = _recordTrade(
            listingId,
            type(uint256).max,
            buyer,
            listing.seller,
            listing.tokenId,
            amount,
            0,          // pricePerUnit (ETH) — not applicable, paid in INR
            priceINR,
            0,          // totalPrice (ETH) — not applicable
            0, 0, 0,    // fees handled off-chain by the payment gateway
            false
        );

        // The actual settlement: move the escrowed tokens to the buyer.
        // No approval needed — this contract already holds them from
        // listing time.
        creditToken.safeTransferFrom(address(this), buyer, listing.tokenId, amount, "");

        // Same tamper-evident audit trail as logINRTrade(), so
        // verifyTrade()/getINRTradeLog() work identically for settled trades.
        bytes32 hash = keccak256(abi.encodePacked(
            tradeId, listing.tokenId, amount, priceINR,
            payMode, buyer, listing.seller, timestamp
        ));
        inrTradeHashes[tradeId] = hash;
        inrTradeLogs[tradeId]   = INRTradeLog({
            tradeId:     tradeId,
            tokenId:     listing.tokenId,
            quantity:    amount,
            priceINR:    priceINR,
            payMode:     payMode,
            buyer:       buyer,
            seller:      listing.seller,
            timestamp:   timestamp,
            tradeHash:   hash,
            blockLogged: block.number
        });

        emit INRTradeLogged(
            tradeId, listing.tokenId, amount, priceINR,
            payMode, buyer, listing.seller, hash, timestamp
        );
    }

    /**
     * @notice Public on-chain verification — anyone can call this.
     *         Regulators, auditors, counterparties can verify any trade
     *         without trusting EtherTrack's database.
     *
     * @return valid         true if supplied params match what was logged
     * @return storedHash    the hash stored on-chain
     * @return blockLogged   block number when trade was logged (0 = not found)
     * @return loggedPayMode 0=INR_WALLET, 1=RAZORPAY, 2=ETH (ETH → use trades mapping)
     */
    function verifyTrade(
        bytes32 tradeId,
        uint256 tokenId,
        uint256 quantity,
        uint256 priceINR,
        uint8   payMode,
        address buyer,
        address seller,
        uint256 timestamp
    ) external view returns (
        bool    valid,
        bytes32 storedHash,
        uint256 blockLogged,
        uint8   loggedPayMode
    ) {
        storedHash   = inrTradeHashes[tradeId];
        blockLogged  = inrTradeLogs[tradeId].blockLogged;
        loggedPayMode = inrTradeLogs[tradeId].payMode;

        if (storedHash == bytes32(0)) {
            return (false, storedHash, blockLogged, loggedPayMode);
        }

        bytes32 recomputed = keccak256(abi.encodePacked(
            tradeId, tokenId, quantity, priceINR,
            payMode, buyer, seller, timestamp
        ));
        valid = (recomputed == storedHash);
    }

    /**
     * @notice Retrieve full INR trade log by DB trade ID.
     */
    function getINRTradeLog(bytes32 tradeId)
        external view returns (INRTradeLog memory)
    {
        require(inrTradeHashes[tradeId] != bytes32(0), "Marketplace: trade not logged");
        return inrTradeLogs[tradeId];
    }

    // ── Signer management ─────────────────────────────────────────────────────
    function setSignerWallet(address _signer) external onlyOwner {
        require(_signer != address(0), "Marketplace: zero address");
        emit SignerWalletUpdated(signerWallet, _signer);
        signerWallet = _signer;
    }

    /// @notice Timelock-compatible setter for signer wallet
    ///         Only callable by TimelockController (after proposal + delay)
    function setSignerWalletViaTimelock(address _signer) external {
        require(msg.sender == address(timelockController), "Marketplace: only timelock");
        require(_signer != address(0), "Marketplace: zero address");
        emit SignerWalletUpdated(signerWallet, _signer);
        signerWallet = _signer;
    }

    /// @notice Repoint this contract at a different KYCRegistry deployment
    ///         without redeploying Marketplace itself. Existing listings,
    ///         balances, and trade history are untouched.
    function setKYCRegistry(address newRegistry) external onlyOwner {
        require(newRegistry != address(0), "Invalid registry address");
        emit KYCRegistryUpdated(address(kycRegistry), newRegistry);
        kycRegistry = KYCRegistry(newRegistry);
    }

    /// @notice Initialize timelock controller reference (call once after deployment)
    /// @dev Only callable by owner before timelock is set
    function initializeTimelock(address _timelockController) external onlyOwner {
        require(address(timelockController) == address(0), "Already initialized");
        timelockController = ITimelockController(_timelockController);
        emit TimelockControllerInitialized(address(0), _timelockController);
    }

    event TimelockControllerInitialized(address indexed oldTimelock, address indexed newTimelock);

    /// @notice Timelock-compatible setter for KYC Registry
    function setKYCRegistryViaTimelock(address newRegistry) external {
        require(msg.sender == address(timelockController), "Marketplace: only timelock");
        require(newRegistry != address(0), "Invalid registry address");
        emit KYCRegistryUpdated(address(kycRegistry), newRegistry);
kycRegistry = KYCRegistry(newRegistry);
    }

    // ═══════════════════════════════════════════════════════════════════════════════════════
    // EXISTING: LIST CREDITS — unchanged
    // ═══════════════════════════════════════════════════════════════════════════════════════

    function listCredit(
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerUnit,
        uint256 pricePerUnitINR,
        uint256 duration
    ) external onlyKYCVerified whenNotPaused returns (uint256 listingId) {
        require(amount > 0,          "Amount must be > 0");
        require(pricePerUnit > 0,    "ETH price must be > 0");
        require(pricePerUnitINR > 0, "INR price must be > 0");
        require(
            creditToken.balanceOf(msg.sender, tokenId) >= amount,
            "Insufficient credits"
        );
        require(!creditToken.isExpired(tokenId), "Credit expired");

        uint256 dur = duration == 0 ? DEFAULT_DURATION : duration;
        require(dur <= MAX_DURATION, "Duration too long");

        listingId = _nextListingId++;

        listings[listingId] = Listing({
            listingId:       listingId,
            seller:          msg.sender,
            tokenId:         tokenId,
            amount:          amount,
            amountRemaining: amount,
            pricePerUnit:    pricePerUnit,
            pricePerUnitINR: pricePerUnitINR,
            listedAt:        block.timestamp,
            expiresAt:       block.timestamp + dur,
            active:          true
        });

        sellerListings[msg.sender].push(listingId);
        tokenListings[tokenId].push(listingId);

        creditToken.safeTransferFrom(msg.sender, address(this), tokenId, amount, "");

        emit CreditListed(listingId, msg.sender, tokenId, amount, pricePerUnit, pricePerUnitINR);

        _tryMatchListing(listingId);
    }

    /**
     * @notice [NEW] Operator-executed listing — lets the backend list a
     *         seller's credits on their behalf, so sellers who trade via
     *         INR never need to open MetaMask for routine listing.
     *
     *         REQUIRES the seller to have called
     *         `creditToken.setApprovalForAll(marketplaceAddress, true)`
     *         ONE TIME (a single one-off approval transaction) — after
     *         that, this function can escrow their tokens with zero
     *         further signatures from the seller, forever.
     */
    function listCreditFor(
        address seller,
        uint256 tokenId,
        uint256 amount,
        uint256 pricePerUnit,
        uint256 pricePerUnitINR,
        uint256 duration
    ) external onlySigner whenNotPaused returns (uint256 listingId) {
        require(kycRegistry.isKYCVerified(seller), "Seller not KYC verified");
        require(amount > 0,          "Amount must be > 0");
        require(pricePerUnit > 0,    "ETH price must be > 0");
        require(pricePerUnitINR > 0, "INR price must be > 0");
        require(
            creditToken.balanceOf(seller, tokenId) >= amount,
            "Insufficient credits"
        );
        require(!creditToken.isExpired(tokenId), "Credit expired");

        uint256 dur = duration == 0 ? DEFAULT_DURATION : duration;
        require(dur <= MAX_DURATION, "Duration too long");

        listingId = _nextListingId++;

        listings[listingId] = Listing({
            listingId:       listingId,
            seller:          seller,
            tokenId:         tokenId,
            amount:          amount,
            amountRemaining: amount,
            pricePerUnit:    pricePerUnit,
            pricePerUnitINR: pricePerUnitINR,
            listedAt:        block.timestamp,
            expiresAt:       block.timestamp + dur,
            active:          true
        });

        sellerListings[seller].push(listingId);
        tokenListings[tokenId].push(listingId);

        // Escrows the seller's tokens into this contract. Requires the
        // seller's one-time setApprovalForAll(marketplace, true) — see
        // NatSpec above.
        creditToken.safeTransferFrom(seller, address(this), tokenId, amount, "");

        emit CreditListed(listingId, seller, tokenId, amount, pricePerUnit, pricePerUnitINR);

        _tryMatchListing(listingId);
    }

    function updateListingPrice(
        uint256 listingId,
        uint256 newPriceEth,
        uint256 newPriceINR
    ) external listingExists(listingId) {
        require(listings[listingId].seller == msg.sender, "Not your listing");
        require(newPriceEth > 0 && newPriceINR > 0, "Price must be > 0");
        listings[listingId].pricePerUnit    = newPriceEth;
        listings[listingId].pricePerUnitINR = newPriceINR;
        emit ListingUpdated(listingId, newPriceEth, newPriceINR);
        _tryMatchListing(listingId);
    }

    function cancelListing(uint256 listingId) external listingExists(listingId) {
        Listing storage listing = listings[listingId];
        require(
            listing.seller == msg.sender || msg.sender == owner(),
            "Not your listing"
        );
        listing.active = false;
        if (listing.amountRemaining > 0) {
            creditToken.safeTransferFrom(
                address(this), listing.seller,
                listing.tokenId, listing.amountRemaining, ""
            );
        }
        emit ListingCancelled(listingId, msg.sender);
    }

    /**
     * @notice [NEW] Operator-executed delisting — returns escrowed tokens
     *         to the seller with zero seller signature required, since the
     *         Marketplace already holds the tokens itself once listed.
     */
    function cancelListingFor(
        address seller,
        uint256 listingId
    ) external onlySigner listingExists(listingId) {
        Listing storage listing = listings[listingId];
        require(listing.seller == seller, "Marketplace: seller mismatch");
        listing.active = false;
        if (listing.amountRemaining > 0) {
            creditToken.safeTransferFrom(
                address(this), seller,
                listing.tokenId, listing.amountRemaining, ""
            );
        }
        emit ListingCancelled(listingId, seller);
    }

    // ═════════════════════════════════════════════════════════════════════════
    // EXISTING: BUY WITH ETH — unchanged
    // ═════════════════════════════════════════════════════════════════════════

    function buyCredit(
        uint256 listingId,
        uint256 amount
    ) external payable onlyKYCVerified whenNotPaused nonReentrant listingExists(listingId) {
        Listing storage listing = listings[listingId];

        require(listing.seller != msg.sender,     "Cannot buy own listing");
        require(amount > 0,                        "Amount must be > 0");
        require(amount <= listing.amountRemaining, "Exceeds available amount");

        uint256 subtotal  = amount * listing.pricePerUnit;
        uint256 buyerFee  = (subtotal * BUYER_FEE_BPS)  / BPS_DENOMINATOR;
        uint256 sellerFee = (subtotal * SELLER_FEE_BPS) / BPS_DENOMINATOR;
        uint256 totalFee  = buyerFee + sellerFee;
        uint256 sellerGets = subtotal - sellerFee;
        uint256 buyerPays  = subtotal + buyerFee;

        require(msg.value >= buyerPays, "Insufficient ETH: send subtotal + 0.5% fee");

        listing.amountRemaining -= amount;
        if (listing.amountRemaining == 0) listing.active = false;

        _recordTrade(
            listingId,
            type(uint256).max,
            msg.sender,
            listing.seller,
            listing.tokenId,
            amount,
            listing.pricePerUnit,
            listing.pricePerUnitINR,
            subtotal,
            buyerFee,
            sellerFee,
            totalFee,
            false
        );

        creditToken.safeTransferFrom(
            address(this), msg.sender, listing.tokenId, amount, ""
        );

        (bool paid,) = listing.seller.call{value: sellerGets}("");
        require(paid, "Seller payment failed");

        treasury.depositFee{value: totalFee}();

        uint256 excess = msg.value - buyerPays;
        if (excess > 0) {
            (bool refunded,) = msg.sender.call{value: excess}("");
            require(refunded, "Refund failed");
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    // EXISTING: BID / ORDER BOOK — unchanged
    // ═════════════════════════════════════════════════════════════════════════

    function placeBuyOrder(
        uint256 tokenId,
        uint256 amount,
        uint256 limitPrice,
        uint256 duration
    ) external payable onlyKYCVerified whenNotPaused returns (uint256 orderId) {
        require(amount > 0, "Amount must be > 0");

        uint256 effectivePrice = limitPrice;
        if (effectivePrice == 0) {
            effectivePrice = _getBestAsk(tokenId);
            require(effectivePrice > 0, "No listings available");
        }

        uint256 totalCost = amount * effectivePrice;
        uint256 buyerFee  = (totalCost * BUYER_FEE_BPS) / BPS_DENOMINATOR;
        require(msg.value >= totalCost + buyerFee, "Insufficient ETH escrowed");

        orderId = _nextOrderId++;

        buyOrders[orderId] = BuyOrder({
            orderId:      orderId,
            buyer:        msg.sender,
            tokenId:      tokenId,
            amount:       amount,
            amountFilled: 0,
            limitPrice:   limitPrice == 0 ? effectivePrice : limitPrice,
            ethEscrowed:  msg.value,
            status:       OrderStatus.OPEN,
            createdAt:    block.timestamp,
            expiresAt:    block.timestamp + (duration == 0 ? 7 days : duration)
        });

        buyerOrders[msg.sender].push(orderId);
        tokenBuyOrders[tokenId].push(orderId);

        emit BuyOrderPlaced(orderId, msg.sender, tokenId, amount, buyOrders[orderId].limitPrice, msg.value);

        _tryMatchBuyOrder(orderId);
    }

    function cancelBuyOrder(uint256 orderId) external nonReentrant {
        BuyOrder storage order = buyOrders[orderId];
        require(order.buyer == msg.sender, "Not your order");
        require(
            order.status == OrderStatus.OPEN ||
            order.status == OrderStatus.PARTIALLY_FILLED,
            "Order not cancellable"
        );

        order.status = OrderStatus.CANCELLED;

        uint256 filledCost   = order.amountFilled * order.limitPrice;
        uint256 filledFee    = (filledCost * BUYER_FEE_BPS) / BPS_DENOMINATOR;
        uint256 amountSpent  = filledCost + filledFee;
        uint256 refundAmount = order.ethEscrowed > amountSpent
            ? order.ethEscrowed - amountSpent : 0;

        if (refundAmount > 0) {
            (bool refunded,) = msg.sender.call{value: refundAmount}("");
            require(refunded, "Refund failed");
        }

        emit BuyOrderCancelled(orderId, msg.sender, refundAmount);
    }

    // ═════════════════════════════════════════════════════════════════════════
    // EXISTING: MATCHING ENGINE — unchanged
    // ═════════════════════════════════════════════════════════════════════════

    function _tryMatchListing(uint256 listingId) internal {
        Listing storage listing = listings[listingId];
        if (!listing.active || listing.amountRemaining == 0) return;

        uint256[] storage orderIds = tokenBuyOrders[listing.tokenId];
        for (uint256 i = 0; i < orderIds.length; i++) {
            if (listing.amountRemaining == 0) break;
            BuyOrder storage order = buyOrders[orderIds[i]];
            if (order.status != OrderStatus.OPEN &&
                order.status != OrderStatus.PARTIALLY_FILLED) continue;
            if (block.timestamp >= order.expiresAt) continue;
            if (order.buyer == listing.seller) continue;
            if (order.limitPrice < listing.pricePerUnit) continue;
            uint256 matchAmount = _min(
                order.amount - order.amountFilled,
                listing.amountRemaining
            );
            if (matchAmount == 0) continue;
            _executeMatch(listingId, orderIds[i], matchAmount, listing.pricePerUnit);
        }
    }

    function _tryMatchBuyOrder(uint256 orderId) internal {
        BuyOrder storage order = buyOrders[orderId];
        if (order.status != OrderStatus.OPEN &&
            order.status != OrderStatus.PARTIALLY_FILLED) return;

        uint256[] storage listingIds = tokenListings[order.tokenId];
        for (uint256 i = 0; i < listingIds.length; i++) {
            if (order.amountFilled >= order.amount) break;
            Listing storage listing = listings[listingIds[i]];
            if (!listing.active) continue;
            if (block.timestamp >= listing.expiresAt) continue;
            if (listing.seller == order.buyer) continue;
            if (listing.pricePerUnit > order.limitPrice) continue;
            uint256 matchAmount = _min(
                order.amount - order.amountFilled,
                listing.amountRemaining
            );
            if (matchAmount == 0) continue;
            _executeMatch(listingIds[i], orderId, matchAmount, listing.pricePerUnit);
        }
    }

    function _executeMatch(
        uint256 listingId,
        uint256 buyOrderId,
        uint256 amount,
        uint256 price
    ) internal {
        Listing  storage listing = listings[listingId];
        BuyOrder storage order   = buyOrders[buyOrderId];

        uint256 subtotal   = amount * price;
        uint256 buyerFee   = (subtotal * BUYER_FEE_BPS)  / BPS_DENOMINATOR;
        uint256 sellerFee  = (subtotal * SELLER_FEE_BPS) / BPS_DENOMINATOR;
        uint256 totalFee   = buyerFee + sellerFee;
        uint256 sellerGets = subtotal - sellerFee;

        listing.amountRemaining -= amount;
        if (listing.amountRemaining == 0) listing.active = false;

        order.amountFilled += amount;
        order.status = order.amountFilled >= order.amount
            ? OrderStatus.FILLED
            : OrderStatus.PARTIALLY_FILLED;

        _recordTrade(
            listingId, buyOrderId,
            order.buyer, listing.seller,
            listing.tokenId, amount,
            price, listing.pricePerUnitINR,
            subtotal, buyerFee, sellerFee, totalFee,
            false
        );

        creditToken.safeTransferFrom(
            address(this), order.buyer, listing.tokenId, amount, ""
        );

        (bool paid,) = listing.seller.call{value: sellerGets}("");
        require(paid, "Seller payment failed");

        treasury.depositFee{value: totalFee}();

        uint256 budgeted   = (amount * order.limitPrice) +
            ((amount * order.limitPrice * BUYER_FEE_BPS) / BPS_DENOMINATOR);
        uint256 actualCost = subtotal + buyerFee;
        if (budgeted > actualCost) {
            uint256 refund = budgeted - actualCost;
            order.ethEscrowed -= refund;
            (bool refunded,) = order.buyer.call{value: refund}("");
            require(refunded, "Refund failed");
        }

        emit MatchExecuted(listingId, buyOrderId, amount, price);
        emit BuyOrderFilled(buyOrderId, amount, order.amount - order.amountFilled);
    }

    // ═════════════════════════════════════════════════════════════════════════
    // EXISTING: VIEW FUNCTIONS — unchanged
    // ═════════════════════════════════════════════════════════════════════════

    function getActiveListings() external view returns (Listing[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < _nextListingId; i++) {
            if (listings[i].active && block.timestamp < listings[i].expiresAt) count++;
        }
        Listing[] memory active = new Listing[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < _nextListingId; i++) {
            if (listings[i].active && block.timestamp < listings[i].expiresAt) {
                active[idx++] = listings[i];
            }
        }
        return active;
    }

    function getOpenBuyOrders() external view returns (BuyOrder[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < _nextOrderId; i++) {
            if ((buyOrders[i].status == OrderStatus.OPEN ||
                 buyOrders[i].status == OrderStatus.PARTIALLY_FILLED) &&
                block.timestamp < buyOrders[i].expiresAt) count++;
        }
        BuyOrder[] memory open = new BuyOrder[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < _nextOrderId; i++) {
            if ((buyOrders[i].status == OrderStatus.OPEN ||
                 buyOrders[i].status == OrderStatus.PARTIALLY_FILLED) &&
                block.timestamp < buyOrders[i].expiresAt) {
                open[idx++] = buyOrders[i];
            }
        }
        return open;
    }

    function getOrderBook(uint256 tokenId) external view returns (
        Listing[]  memory asks,
        BuyOrder[] memory bids
    ) {
        uint256[] storage lIds = tokenListings[tokenId];
        uint256 askCount = 0;
        for (uint256 i = 0; i < lIds.length; i++) {
            if (listings[lIds[i]].active && block.timestamp < listings[lIds[i]].expiresAt) askCount++;
        }
        asks = new Listing[](askCount);
        uint256 ai = 0;
        for (uint256 i = 0; i < lIds.length; i++) {
            if (listings[lIds[i]].active && block.timestamp < listings[lIds[i]].expiresAt) {
                asks[ai++] = listings[lIds[i]];
            }
        }

        uint256[] storage bIds = tokenBuyOrders[tokenId];
        uint256 bidCount = 0;
        for (uint256 i = 0; i < bIds.length; i++) {
            BuyOrder storage o = buyOrders[bIds[i]];
            if ((o.status == OrderStatus.OPEN || o.status == OrderStatus.PARTIALLY_FILLED) &&
                block.timestamp < o.expiresAt) bidCount++;
        }
        bids = new BuyOrder[](bidCount);
        uint256 bi = 0;
        for (uint256 i = 0; i < bIds.length; i++) {
            BuyOrder storage o = buyOrders[bIds[i]];
            if ((o.status == OrderStatus.OPEN || o.status == OrderStatus.PARTIALLY_FILLED) &&
                block.timestamp < o.expiresAt) {
                bids[bi++] = o;
            }
        }
    }

    function getSellerListings(address seller) external view returns (uint256[] memory) { return sellerListings[seller]; }
    function getBuyerOrders(address buyer)     external view returns (uint256[] memory) { return buyerOrders[buyer]; }
    function getBuyerTrades(address buyer)     external view returns (uint256[] memory) { return buyerTrades[buyer]; }
    function getSellerTrades(address seller)   external view returns (uint256[] memory) { return sellerTrades[seller]; }
    function getTrade(uint256 tradeId)         external view returns (Trade memory)     { return trades[tradeId]; }

    function calculateBuyerCost(uint256 amount, uint256 pricePerUnit) external pure returns (
        uint256 subtotal, uint256 buyerFee, uint256 totalBuyerPays
    ) {
        subtotal       = amount * pricePerUnit;
        buyerFee       = (subtotal * BUYER_FEE_BPS) / BPS_DENOMINATOR;
        totalBuyerPays = subtotal + buyerFee;
    }

    function calculateSellerReceives(uint256 amount, uint256 pricePerUnit) external pure returns (
        uint256 subtotal, uint256 sellerFee, uint256 sellerReceives
    ) {
        subtotal       = amount * pricePerUnit;
        sellerFee      = (subtotal * SELLER_FEE_BPS) / BPS_DENOMINATOR;
        sellerReceives = subtotal - sellerFee;
    }

    function totalListings()  external view returns (uint256) { return _nextListingId; }
    function totalBuyOrders() external view returns (uint256) { return _nextOrderId;   }
    function totalTrades()    external view returns (uint256) { return _nextTradeId;   }

    function shouldUseAMM(uint256 amount) public view returns (bool) {
        return ammPool != address(0) && amount <= ammThreshold;
    }

    function setAMMPool(address _ammPool) external onlyOwner {
        ammPool = _ammPool;
        emit AMMPoolSet(_ammPool);
    }

    function setAMMThreshold(uint256 threshold) external onlyOwner {
        ammThreshold = threshold;
        emit AMMThresholdUpdated(threshold);
    }

    function _getBestAsk(uint256 tokenId) internal view returns (uint256 bestPrice) {
        uint256[] storage lIds = tokenListings[tokenId];
        bestPrice = type(uint256).max;
        for (uint256 i = 0; i < lIds.length; i++) {
            Listing storage l = listings[lIds[i]];
            if (l.active && block.timestamp < l.expiresAt) {
                if (l.pricePerUnit < bestPrice) bestPrice = l.pricePerUnit;
            }
        }
        if (bestPrice == type(uint256).max) bestPrice = 0;
    }

    function _recordTrade(
        uint256 listingId,
        uint256 buyOrderId,
        address buyer,
        address seller,
        uint256 tokenId,
        uint256 amount,
        uint256 price,
        uint256 priceINR,
        uint256 totalPrice,
        uint256 buyerFee,
        uint256 sellerFee,
        uint256 totalFee,
        bool    isAMM
    ) internal returns (uint256 tradeId) {
        tradeId = _nextTradeId++;
        trades[tradeId] = Trade({
            tradeId:         tradeId,
            listingId:       listingId,
            buyOrderId:      buyOrderId,
            buyer:           buyer,
            seller:          seller,
            tokenId:         tokenId,
            amount:          amount,
            pricePerUnit:    price,
            pricePerUnitINR: priceINR,
            totalPrice:      totalPrice,
            buyerFee:        buyerFee,
            sellerFee:       sellerFee,
            totalFee:        totalFee,
            tradedAt:        block.timestamp,
            isAMM:           isAMM
        });
        buyerTrades[buyer].push(tradeId);
        sellerTrades[seller].push(tradeId);

        emit CreditTraded(
            tradeId, listingId, buyOrderId,
            buyer, seller, tokenId,
            amount, price, priceINR,
            totalPrice, buyerFee, sellerFee, totalFee, isAMM
        );
    }

    function _min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }

    // ── ERC1155 receiver ──────────────────────────────────────────────────────
    function onERC1155Received(
        address, address, uint256, uint256, bytes calldata
    ) external pure override returns (bytes4) {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(
        address, address, uint256[] calldata, uint256[] calldata, bytes calldata
    ) external pure override returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return interfaceId == type(IERC1155Receiver).interfaceId;
    }

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    receive() external payable {}
}

contracts/Treasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title Treasury
 * @author EtherTrack
 * @notice Collects and manages platform fees from all trades.
 *         0.5% fee on every trade — collected in MATIC.
 *
 * BLOCKCHAIN MIGRATION: Replaces display-only fee in CarbonCredits.js
 */
contract Treasury is Ownable, Pausable, ReentrancyGuard {

    // ── State ─────────────────────────────────────────────
    uint256 public constant FEE_BASIS_POINTS = 50;  // 0.5% = 50/10000
    uint256 public constant BASIS_POINTS_DENOMINATOR = 10000;

    uint256 public totalFeesCollected;
    uint256 public totalFeesWithdrawn;

    // Authorized contracts that can deposit fees (Marketplace)
    mapping(address => bool) public authorizedDepositors;

    // ── Events ────────────────────────────────────────────
    event FeeDeposited(address indexed from, uint256 amount, uint256 totalCollected);
    event FeeWithdrawn(address indexed to, uint256 amount);
    event DepositorAuthorized(address indexed depositor);
    event DepositorRevoked(address indexed depositor);

    // ── Modifiers ─────────────────────────────────────────
    modifier onlyAuthorized() {
        require(authorizedDepositors[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    // ── Constructor ───────────────────────────────────────
    constructor(address initialOwner) Ownable(initialOwner) {}

    // ── Fee Management ────────────────────────────────────

    /**
     * @notice Calculate platform fee for a given trade amount
     * BLOCKCHAIN MIGRATION: Replaces tradeFee = tradeTotal * PLATFORM_FEE in CarbonCredits.js
     */
    function calculateFee(uint256 amount) public pure returns (uint256) {
        return (amount * FEE_BASIS_POINTS) / BASIS_POINTS_DENOMINATOR;
    }

    /**
     * @notice Deposit fee — called by Marketplace on every trade
     */
    function depositFee() external payable onlyAuthorized whenNotPaused {
        require(msg.value > 0, "Fee must be > 0");
        totalFeesCollected += msg.value;
        emit FeeDeposited(msg.sender, msg.value, totalFeesCollected);
    }

    /**
     * @notice Withdraw collected fees to owner (EtherTrack company wallet)
     */
    function withdrawFees(uint256 amount) external onlyOwner nonReentrant {
        require(amount <= address(this).balance, "Insufficient balance");
        totalFeesWithdrawn += amount;
        (bool success, ) = owner().call{value: amount}("");
        require(success, "Withdrawal failed");
        emit FeeWithdrawn(owner(), amount);
    }

    function withdrawAllFees() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");
        totalFeesWithdrawn += balance;
        (bool success, ) = owner().call{value: balance}("");
        require(success, "Withdrawal failed");
        emit FeeWithdrawn(owner(), balance);
    }

    // ── Depositor Management ──────────────────────────────
    function authorizeDepositor(address depositor) external onlyOwner {
        authorizedDepositors[depositor] = true;
        emit DepositorAuthorized(depositor);
    }

    function revokeDepositor(address depositor) external onlyOwner {
        authorizedDepositors[depositor] = false;
        emit DepositorRevoked(depositor);
    }

    // ── View Functions ────────────────────────────────────
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getPendingWithdrawal() external view returns (uint256) {
        return address(this).balance;
    }

    // ── Admin ─────────────────────────────────────────────
    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    receive() external payable {
        totalFeesCollected += msg.value;
        emit FeeDeposited(msg.sender, msg.value, totalFeesCollected);
    }
}

